(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["hr"] = {"ui":{"skip":"Preskoči na sadržaj","back":"← Natrag na AI-gile","lang.button":"Jezik: {name}","lang.dialog":"Odaberi jezik","lang.search":"Traži jezike","lang.none":"Nijedan jezik ne odgovara","lang.notYet":"{name} još nije preveden","theme.aria":"Promijeni temu: svijetla, tamna ili crna","theme.toLight":"Prebaci na svijetlu temu","theme.toDark":"Prebaci na tamnu temu","theme.toBlack":"Prebaci na crnu temu (prava crna, ugodna za OLED ekrane)","words.underline":"Podcrtaj ove riječi na stranici","words.underlineHelp":"Prijeđi mišem preko riječi s točkastom crtom ili je dodirni da vidiš što znači.","words.col.todo":"Kartice odabrane za sada: tim sljedeće kreće s njima.","words.col.doing":"Neki AI trenutačno radi na ovoj kartici.","words.col.review":"Jedan je AI završio posao; drugi ga provjerava prije nego stigne do tebe.","words.col.verify":"Čeka se tebe: isprobaj i reci radi li.","words.col.team":"Tvoje bilješke ili odgovori, koji čekaju da ih tim preuzme.","words.col.done":"Gotovo i prihvaćeno.","index.title":"AI-gile: tvoj AI razvojni tim, na jednoj ploči","index.description":"AI-gile je kanban ploča za AI timove koji programiraju. Rade dok ti spavaš; tebi ostaje jedna kratka hrpa stvari koje trebaš odlučiti, testirati i prihvatiti.","hero.logoAlt":"Ikona AI-gile ploče","hero.h1.html":"Tvoj AI razvojni tim, na jednoj&nbsp;ploči.","hero.alpha":"🐣 Zatvorena pre-alfa","hero.alphaTitle":"Rano je i nedovršeno: hvala što isprobavaš!","hero.lede":"Grade dok ti spavaš. Budiš se uz jednu kratku hrpu: nekoliko pitanja, nekoliko stvari za testiranje, jedan ili dva ljubičasta dijamanta. Klikneš, prihvatiš, vratiš se kavi.","dl.windows":"Windows aplikacija","dl.browser":"Pokreni u pregledniku","dl.messenger":"📱 Messenger za tvoj mobitel","dl.soon":"Uskoro","dl.notify":"🔔 Javi mi kad se otvori","dl.notifySmall":"Alfa ili beta","hero.secondary":"Agile, ali timu ne treba stand-up kava. (Stand-up ipak održavaju.)","pitch.h2":"AI-gile u onoliko riječi koliko želiš","pitch.lede":"Odaberi duljinu, od jedne riječi do 144. Svaka duljina ima svoj opis, napisan baš za tu veličinu. Povuci klizač ili koristi strelice.","pitch.rangeLabel":"Duljina u riječima","pitch.dice":"🎲 druga verzija","pitch.words.one":"{n} riječ","pitch.words.other":"{n} riječi","pitch.letters.one":"{n} slovo","pitch.letters.other":"{n} slova","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znakova","count.line.html.one":"{n} kartica na ploči upravo sada","count.line.html.other":"{n} kartica na ploči upravo sada","people.humans.html.one":"👥 {n} čovjek","people.humans.html.other":"👥 {n} ljudi","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agenata","people.working.html.one":"⚡ {n} radi upravo sada","people.working.html.other":"⚡ {n} radi upravo sada","pre.title":"AI-gile: ovdje se nešto gradi","pre.description":"Ovdje se nešto gradi. Ploča na kojoj AI timovi grade ono što tražiš i usput te uče. Zasad zatvorena pre-alfa s prijateljima.","pre.h1":"Ovdje se nešto gradi. 🤫","pre.line":"Ploča na kojoj AI timovi grade ono što tražiš i usput te uče. Zasad zatvorena pre-alfa s prijateljima.","pre.btn":"🔔 Javi mi kad se otvori","pre.peek":"Iza stakla: prava ploča, uživo. Svaka kartica je obojena traka.","pre.peekFake":"Iza stakla: ovako izgleda ploča u radu.","pre.night":"🌙 Noćni čuvar je zadužen · 😴 čovjek odmara","features.aria":"Što radi","f.pile.h":"Jedna hrpa za tebe","f.pile.html":"<b>Za tebe</b> sadrži sve što čeka tebe, kroz sve projekte: pitanja, stvari za testiranje, zadatke koje može obaviti samo čovjek. Tvoj red kaže što je sljedeće i koliko traje.","f.sleep.h":"Timovi koji rade dok ti spavaš","f.sleep.p":"Svaki projekt ima lead i tim AI agenata. Komentiraj karticu i tim se budi, odradi posao i vrati je s koracima koje može pratiti i umoran čovjek.","f.tester.h":"AI tester provjerava prvi","f.tester.p":"Prije nego išta stigne do tebe, tester prati korake u kopiji aplikacije i pokazuje što je vidio, sa snimkom zaslona. Prelistaj one koje su prošle i prihvati jednim klikom.","f.proof.h":"Dokazi, ne obećanja","f.proof.p":"Svaka primopredaja pokazuje što se promijenilo: datoteke, diff, snimke zaslona. Ne moraš otvarati svaku aplikaciju da vidiš je li gotovo.","f.chat.h":"Razgovaraj sa svojim leadovima","f.chat.p":"Traka u stilu Discorda: jedna ikona po projektu, ljubičasti dijamanti za ono što treba tebe. Pošalji leadu ideju; pretvorit će je u kartice i plan, s gumbom ✅ Go.","f.tidy.h":"Sam se uredi","f.tidy.p":"Povezane kartice stapaju se u jednu, zbrkani naslovi se ispravljaju, a provjera tokena drži kod vitkim. Manje stvari između kojih se prebacuješ, manje razmišljanja.","f.private.h":"Tvoje, na tvom računalu","f.private.li1":"Ploča radi na tvom računalu i odgovara samo tebi.","f.private.li2":"Privatne poruke među ljudima šifrirane su od kraja do kraja.","f.private.li3":"Bez računa, bez tragača, bez kolačića.","f.lang.h":"Na tvom jeziku","f.lang.p":"Više od 120 jezika, od nizozemskog, velškog i japanskog do gusarskog, Yode i klingonskog, s brzim povratkom na engleski za stručne pojmove.","f.service.h":"Od ideje do pravog servisa","f.service.p":"Napravio si nešto s AI-jem što ljudi sada koriste? Označi to kao servis i ploča ti pomaže da ga dobro vodiš: provjere dostupnosti, javna statusna stranica, incidenti s pisanom analizom, promjene kojima treba Go, sigurnosne kopije provjerene svaki dan. Pomoć te uči svaki korak usput.","msgr.h2":"AI-gile Messenger: tvoj tim u džepu","msgr.p1":"Razgovaraj sa svojim AI timom bez otvaranja ploče. Dopisuj se s leadovima svojih projekata i s prijateljima, pogledaj korake testiranja kartice i odgovori na njih, sve s mobitela.","msgr.p2":"Za uparivanje skeniraj QR kod na svojoj ploči. Prvi put? Prijateljski demo razgovor provest će te kroz sve.","msgr.when":"Prvo Android, zatim web verzija za mobitele i iPhone.","msgr.who":"Lead tvog projekta","msgr.b1":"Popravak tamnog načina je spreman. Želiš korake za testiranje?","msgr.b2":"Da, molim!","msgr.b3":"1. Otvori Postavke. 2. Odaberi Tamna. Izgleda li dobro?","tl.aria":"Vremenska crta od prvog razgovora do plana","tl.h2":"Od prvog razgovora do onoga što slijedi","tl.lede":"Pravi datumi i vremena, u tvojoj vremenskoj zoni. Nakon današnjeg dana to je plan, bez obećanih datuma.","tl.today":"Danas","tl.planned":"planirano","tl.doing":"u tijeku","tl.cards.one":"{n} kartica","tl.cards.other":"{n} kartica","join.h2":"Pridruži se","join.lede":"AI-gile gradi jedan bradati čudak s AuDHD-om i nekoliko bitaka s psihičkim zdravljem te velik broj strpljivih agenata. Zasad je privatan, u zatvorenoj alfi s prijateljima. Želiš li probati kad se otvori?","join.btn":"Prijavi interes","join.small":"Javit ćemo ti se e-poštom, ništa više","footer.tag":"AI-gile. Bez tragača, bez kolačića, bez stand-up kave.","footer.licence":"Poslovna licenca","footer.status":"Status","footer.privacy":"Što čuvamo","footer.thanks":"Pozive omogućuje ChilledChat","form.sending":"Šaljem…","form.failed":"Nije uspjelo: pokušaj ponovno kasnije.","form.offline":"Nije moguće doći do AI-gilea: pokušaj ponovno kasnije.","form.keep":"Ovo koristimo samo da ti odgovorimo, a zatim brišemo. Bez tragača, bez kolačića.","form.keepLink":"Što čuvamo","interest.title":"AI-gile: javi mi kad se alfa otvori","interest.description":"Ostavi e-adresu da saznaš kad se otvori zatvorena alfa ili beta AI-gilea.","interest.h1":"🔔 Javi mi kad se otvori","interest.lede":"AI-gile je u zatvorenoj pre-alfi. Ostavi e-adresu i javit ćemo se jednom, kad bude mjesta za tebe.","interest.email":"Tvoja e-adresa","interest.which":"Koje testiranje?","interest.alpha":"Zatvorena alfa: rano, grubo, puno promjena","interest.beta":"Beta: stabilnija, kasnije","interest.both":"Svejedno, što prije dođe","interest.submit":"Stavi me na popis","interest.thanks":"Hvala! Na popisu si.","licence.title":"AI-gile: poslovna licenca","licence.description":"Koristiš AI-gile u poslu? Zatraži besplatnu poslovnu licencu.","licence.h1":"📜 Poslovna licenca","licence.lede":"Koristiš AI-gile na poslu? Reci nam tko si i čime se baviš. Ako donosi nešto dobro, licenca je besplatna.","licence.company":"Tvrtka","licence.website":"Web-stranica","licence.what":"Čime se baviš","licence.how":"Kako to pomaže svijetu","licence.email":"E-adresa","licence.submit":"Prijavi se","licence.thanks":"Hvala! Odgovorit ćemo e-poštom.","status.title":"Status AI-gilea","status.h1":"Status AI-gilea","status.quiet":"Sve je mirno","status.intro":"Radi li AI-gile upravo sada? Ova stranica svakih 5 minuta provjerava web-stranicu, dijeljenje ploča, pozive i preuzimanje.","status.up":"Radi (odgovor stigao za {ms} ms)","status.slow":"Bez odgovora na zadnju provjeru, pokušavam ponovno","status.down":"Ne radi: bez odgovora na zadnje dvije provjere","status.svc.web":"Web-stranica","status.svc.web.offers":"Ova stranica: što je AI-gile i obrazac za prijavu interesa","status.svc.boards":"Dijeljenje ploča","status.svc.boards.offers":"Javne ploče, poruke među prijateljima i pozivnice","status.svc.calls":"Pozivi","status.svc.calls.offers":"Glas, video i dijeljenje zaslona u AI-gileu","status.svc.download":"Preuzimanje","status.svc.download.offers":"Instalacijski program za Windows i poveznice pozivnica","status.checking":"Provjeravam…","status.offline":"Trenutno nije moguće doći do statusne usluge (pokušavam ponovno)","status.updated":"ažurirano {ago}","status.justNow":"upravo sada","status.min":"prije {n} min","status.hours":"prije {n} h","status.days":"prije {n} d","privacy.title":"AI-gile: što čuvamo","privacy.h1":"Što čuvamo","privacy.lede":"Ukratko: samo ono što nam pošalješ, i to ne dugo.","privacy.only":"Samo ono što nam pošalješ: ono što upišeš u obrazac, poput tvoje e-adrese. Ništa drugo o tebi.","privacy.sealed":"Zapečaćeno je tako da ga naš poslužitelj ne može pročitati: u tvom pregledniku prije nego što krene (u starijem pregledniku, čim stigne). Otvoriti ga može samo naša vlastita ploča.","privacy.server":"Briše se s poslužitelja čim stigne na našu ploču. Sve što je ondje i nakon 30 dana svejedno se briše.","privacy.board":"Na našoj ploči čuvamo ga samo dok ti ne odgovorimo, a onda ga brišemo i ondje.","privacy.none":"Bez tragača, bez kolačića, bez analitike.","privacy.local":"Tvoj jezik i izbor svijetle ili tamne teme ostaju u tvom pregledniku. Nikad nam se ne šalju.","privacy.ask":"Želiš da nestane prije? Odgovori na našu poruku e-pošte i javi nam.","live.h2":"Gledajte kako se gradi, uživo","live.caption":"Svaka kartica je skrivena: vidite oblik posla, a ne riječi.","live.watching.one":"uživo: {n} gleda","live.watching.other":"uživo: {n} gleda","live.last.now":"Zadnja kartica premještena upravo sada","live.last.min.one":"Zadnja kartica premještena prije {n} min","live.last.min.other":"Zadnja kartica premještena prije {n} min","live.last.hour.one":"Zadnja kartica premještena prije {n} sat","live.last.hour.other":"Zadnja kartica premještena prije {n} sati","live.last.day.one":"Zadnja kartica premještena prije {n} dan","live.last.day.other":"Zadnja kartica premještena prije {n} dana","live.offline":"Ploča uživo malo odmara. Svratite uskoro.","live.cols":"Backlog|Na redu|U tijeku|Tim provjerava|Za tvoje testiranje|Za tim|Gotovo","pitch.words.few":"{n} riječi","pitch.letters.few":"{n} slova","pitch.chars.few":"{n} znaka","count.line.html.few":"{n} kartice na ploči upravo sada","tl.cards.few":"{n} kartice"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegirano."]},{"n":2,"texts":["Kanban robota.","Agenti, posloženi.","Ideje, izgrađene."]},{"n":3,"texts":["Kanban za robote.","Ideje postaju značajke.","Besplatni agentski kanban."]},{"n":5,"texts":["Kanban ploča koju vode agenti.","Ti pišeš kartice. Agenti grade.","Besplatno, lokalno, testirano, pomalo ludo."]},{"n":8,"texts":["Besplatna kanban ploča na kojoj rade AI agenti.","Napiši ideju. Agenti je grade. Ti prihvaćaš.","Agile za jednog čovjeka i mnogo strpljivih robota."]},{"n":13,"texts":["Kanban ploča na tvom računalu, a kartice preuzimaju AI agenti i rade ih.","Napiši ideju. Tim agenata je izgradi. Tester je provjeri prije tebe.","Besplatno, bez računa, bez tragača: ploča, nekoliko robota i ti kao šef."]},{"n":21,"texts":["AI-gile je kanban ploča za rad s AI agentima koji programiraju. Oni preuzimaju kartice; ti ih testiraš i prihvaćaš.","Svaki projekt dobiva lead i tim AI agenata. Komentiraj bilo koju karticu i tim odmah kreće raditi.","Besplatna osobna ploča zadataka koja radi na tvom računalu. Radnici su roboti. Onaj koji kaže da si ti."]},{"n":34,"texts":["Ideje stavljaš na ploču. Tim AI agenata pretvara ih u značajke koje rade, testira ih i vraća ti ih s koracima za isprobavanje. Ništa ne vrijedi kao gotovo dok ti to ne kažeš.","AI-gile je domaća kanban ploča koju je Rich izgradio uz mnogo pomoći agenata kojima sada upravlja. Besplatna je, radi na tvom računalu i dijeli se s prijateljima, ne prodaje se.","Zamisli običnu kanban ploču sa stupcima od Backloga do Gotovo, samo što kartice preuzimaju AI agenti. Javljaju napredak, pitaju kad zapnu i uvijek čekaju tvoj palac gore."]},{"n":55,"texts":["AI-gile je kanban ploča na kojoj je tim sastavljen od AI agenata. Svaki projekt ima lead koji planira posao i pomoćnike koji ga grade. Kad je značajka gotova, AI tester je isproba i snimi zaslon, a zatim stiže na tvoju hrpu. Prihvati je ili komentiraj pa je prerade.","Počelo je kao jedan način da jedna osoba prati mnogo AI programerskih sesija odjednom, a preraslo je u pravu ploču. Radi na tvom računalu, ne traži račun i nema tragača. Besplatna je za prijatelje i svakoga tko je znatiželjan. Također je nedovršena, pa očekuj grube rubove i poneko iznenađenje.","Evo poštene verzije, bez uljepšavanja. I dalje ti moraš imati ideje i provjeravati rezultate. AI-gile radi sve između: drži kartice u redu, budi pravog agenta kad komentiraš, pokazuje točno što se promijenilo, tko je to napravio i sve to drži na jednoj kratkoj hrpi za tebe."]},{"n":89,"texts":["AI-gile je besplatna kanban ploča koju pokrećeš na vlastitom računalu. Umjesto ljudi, svaki projekt ima tim AI agenata: lead koji tvoje ideje pretvara u kartice i plan te pomoćnike koji preuzimaju kartice po prioritetu. Kad je nešto izgrađeno, AI tester prati korake testiranja i pokazuje ti što je vidio. Zatim sve čeka na jednoj hrpi nazvanoj Za tebe. Prihvatiš to ili komentiraš pa tim pokuša ponovno. Ništa ne stiže u Gotovo bez tebe.","Nekoliko stvari koje možda ne očekuješ. Noćni čuvar dopunjuje stupac Na redu dok ti spavaš, birajući kartice kojima ne treba tvoj odgovor. Brojač tokena pokazuje koliko su agenti potrošili danas i ovaj tjedan, a način bez tokena kaže im da prestanu trošiti. Možeš slati poruke prijateljima, a privatne poruke šifrirane su od kraja do kraja. Ploča govori oko 120 jezika, uključujući nizozemski, flamanski, gusarski i klingonski. Sve je besplatno, a nitko ti to ne pokušava ni prodati.","AI-gile je mali osobni projekt, a ne tvrtka. Rich je želio brinuti o nekoliko AI projekata bez otvaranja svake aplikacije da provjeri stanje, pa su on i agenti izgradili ploču za to, a zatim su tu ploču koristili za gradnju ostatka sebe. U zatvorenoj je pre-alfi, što znači da radi, uglavnom, za šačicu prijatelja. Nema stranice s cijenama, nema newslettera i nema plana rasta. Ako ti zvuči korisno, možeš se javiti da probaš kad se malo više otvori."]},{"n":144,"texts":["AI-gile je kanban ploča za jednog čovjeka i mnogo AI agenata. Radi na tvom računalu i potpuno je besplatna, bez računa i bez ikakvih tragača, a tvoji podaci ostaju kod tebe. Dodaješ projekte, a svaki projekt dobiva lead i mali tim. S leadom razgovaraš, pomalo kao na Discordu, i opišeš ideju; lead je pretvara u kartice i plan, pa čeka da pritisneš Go. Tim prolazi kroz kartice po prioritetu, koristeći jednostavnu naredbenu liniju napravljenu za jezične modele. Prije nego išta stigne natrag do tebe, AI tester prati korake u kopiji aplikacije i prilaže snimku zaslona. Gotov posao stiže na tvoju hrpu s promijenjenim datotekama i diffom. Prihvatiš ga ili ostaviš komentar, pa se tim probudi i pokuša ponovno. Samo ti možeš premjestiti karticu u Gotovo.","Otprilike ovako izgleda dan s AI-gileom. Navečer ostaviš nekoliko komentara: ovaj je gumb na krivom mjestu, taj popis treba sortirati, može li tamna tema. Odeš spavati. Agenti pročitaju komentare, naprave izmjene, testiraju ih i vrate ti ih. Ako stupac Na redu presuši, noćni čuvar ga puni iz backloga karticama kojima ne treba tvoj odgovor. Ujutro te čeka jedna kratka hrpa: par pitanja i nekoliko stvari za isprobati, svaka s koracima koje može pratiti pospana osoba i snimkom zaslona na kojoj radi. Pregledaš ih klikom, prihvatiš dobre, a ostale vratiš. Brojač tokena pokazuje koliko je sve to potrošilo, a način bez tokena tu je za štedljive tjedne. Zatim doručkuješ, a u tome ti agenti još ne mogu pomoći.","Prvo, što AI-gile nije. Nije startup, nije na prodaju i nitko ne prikuplja tvoje podatke. To je besplatna ploča koja radi na tvom računalu, bez računa, bez tragača i bez kolačića. Što jest: jedno uredno mjesto na kojem vidiš sve AI programerske projekte odjednom, s timom agenata koji rade kartice i tobom koji donosiš odluke. Spaja povezane kartice, ispravlja zbrkane naslove i pazi koliko kod ostaje vitak. Govori oko 120 jezika, od nizozemskog i flamanskog do gusarskog i klingonskog. Prijatelji mogu slati poruke jedni drugima, privatno i šifrirano. Izgradili su ga Rich i velik broj strpljivih agenata, uglavnom koristeći sam program. U zatvorenoj je pre-alfi, pa je mjestimice grub. Ako ti zvuči zabavno, lijepo zamoli i možda uđeš rano."]}],"quips":{"1":"Jedna riječ. Hrabro. Možda i previše hrabro.","3":"Tri riječi. Već iskrenije od većine stranica proizvoda.","8":"Osam riječi. I dalje kraće od stand-upa.","21":"Duljine su, usput, story pointovi. Naravno da jesu.","55":"Pedeset i pet riječi. Dok si čitao, dvije su kartice završene.","144":"To je ona duga. Nema 233. Agenti su otišli spavati."}},"timeline":{"first-idea.name":"Prva ideja","first-idea.line":"Sasvim prvi razgovor, prije nego što je postojao ijedan redak koda.","first-board.name":"Prva ploča","first-board.line":"Ploča koja prati vlastitu izgradnju: kartice, stupci, povuci i ispusti, projekti.","team-roles.name":"Tim i uloge","team-roles.line":"Profili agenata, predlošci timova, prostori i tko što radi.","install.name":"Instalacija i izdanja","install.line":"Zip koji prijatelj može instalirati, samoažuriranje, kanali i vraćanje unatrag.","usage-saver.name":"Štednja potrošnje","usage-saver.line":"Mjeri što pokretanja koštaju, drži kod vitkim, štedi svoj limit.","friends.name":"Prijatelji i dijeljenje","friends.line":"Privatne poruke, pomiješani relej, pozivnice, uloge i zajednički projekti.","languages.name":"Jezici","languages.line":"Svaki tekst na zaslonu u jezičnoj datoteci, prvo nizozemski i flamanski.","ai-tester.name":"AI tester","ai-tester.line":"Tester prvi provjerava svaku primopredaju i pokazuje što je vidio.","website.name":"Web-stranica","website.line":"aigile.lol, teaser i ova vremenska crta.","streaming.name":"Chat i streaming","streaming.line":"Discord, Twitch, OBS, streamerski način, GIF-ovi i emojiji.","no-ai.name":"Izdanje bez AI-ja","no-ai.line":"Ploča za ljude koji programiraju bez AI-ja i javne ploče.","night-watch.name":"Noćni čuvar","night-watch.line":"Čuvar i Scrum Master drže timove na zadatku dok ti spavaš.","p-more.name":"Sve ostalo","p-more.line":"Manje ideje koje još čekaju svoj red.","p-android.name":"Mobitel i Android","p-android.line":"Dođi do ploče s mobitela, a zatim prava Android aplikacija.","p-release.name":"Alfa i dalje","p-release.line":"Zatvorena alfa, stranica uživo, zatim beta.","p-languages.name":"Još jezika","p-languages.line":"130 jezika i način uranjanja za one koji uče.","p-engines.name":"Još AI motora","p-engines.line":"Odaberi Claude, Codex, Gemini, Copilot ili Cursor za svakog agenta.","p-pro.name":"Profesionalna praksa","p-pro.line":"Oznake rizika, merge vrata, kartice incidenata i zaštitne ograde.","p-self.name":"Briga o tebi","p-self.line":"Način za umorne, podsjetnici za brigu o sebi i 4:20.","p-servers.name":"Poslužitelji i rast","p-servers.line":"Globalne postavke poslužitelja, uloge i planiranje rasta.","p-livestream.name":"Streaming dodaci","p-livestream.line":"Twitch chat, vlastiti emojiji i javni prikaz uživo."},"words":{"button":"📖 Stručni pojmovi","h":"📖 Pojmovi objašnjeni","intro":"Besplatna obuka običnim jezikom: svaka riječ na koju naiđeš, od prve ideje do usluge na koju se ljudi oslanjaju, uz Agile, izradu, održavanje sigurnosti i rad s AI-jem usput.","search":"Traži riječ…","none":"Nijedna riječ ne odgovara.","close":"Zatvori","count":{"one":"{count} riječ","other":"{count} riječi"},"groups":[{"id":"idea","name":"💡 Ideja i istraživanje"},{"id":"plan","name":"🗺️ Planiranje posla"},{"id":"agile","name":"🔁 Agilni načini rada"},{"id":"build","name":"🛠️ Izrada"},{"id":"test","name":"🧪 Testiranje i kvaliteta"},{"id":"change","name":"🔀 Sigurno mijenjanje"},{"id":"run","name":"🛎️ Vođenje servisa"},{"id":"sec","name":"🔒 Sigurnost i privatnost"},{"id":"ai","name":"🤖 Rad s AI-jem"},{"id":"money","name":"💰 Novac i licence"}],"list":[{"id":"discovery","g":"idea","word":"Istraživanje (Discovery)","text":"Rana faza u kojoj otkrivaš koji problem vrijedi riješiti i za koga, prije nego što se išta počne graditi.","also":["faza istraživanja","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Opis problema","text":"Jedna ili dvije rečenice o tome tko ima problem, što je to i zašto je važno, da svi ciljaju isto.","also":["opisi problema","opisa problema","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Korisnik","text":"Osoba koja koristi ono što izrađuješ. Posao se radi zbog njezinih potreba.","also":["korisnici","korisnika","korisniku","korisnicima","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Dionik (Stakeholder)","text":"Svatko kome je stalo do ishoda posla ili na koga on utječe, poput ljudi koji ga plaćaju, koriste ili podržavaju.","also":["dionici","dionika","dionicima","zainteresirane strane","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Izmišljena, ali realistična osoba koja predstavlja jednu vrstu korisnika, da se tim može pitati „bi li Samu ovo bilo lako?“","also":["persone","personu","personom","persona","personas"]},{"id":"userresearch","g":"idea","word":"Istraživanje korisnika","text":"Razgovor sa stvarnim ljudima i promatranje što rade, da saznaš što im treba, umjesto da nagađaš.","also":["intervjui s korisnicima","user research","user interviews"]},{"id":"journey","g":"idea","word":"Korisnički put (User journey)","text":"Koraci kroz koje osoba prolazi da nešto obavi, od prvog saznanja do kraja, i izvan tvog proizvoda. Kad ga nacrtaš, vidi se gdje zapinju.","also":["korisnički putovi","korisničkog puta","korisničkom putu","put klijenta","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Bolna točka (Pain point)","text":"Nešto što ljude danas smeta ili usporava. Dobri proizvodi uklanjaju bolne točke.","also":["bolne točke","bolnu točku","bolnih točaka","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Pretpostavka","text":"Nešto u što vjeruješ, ali to još nije provjereno. Kad pretpostavke zapišeš, vidiš što prvo testirati.","also":["pretpostavke","pretpostavku","pretpostavki","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipoteza","text":"Najbolja pretpostavka koju planiraš provjeriti, s onim što očekuješ, na primjer „ljudi će se registrirati ako je prvi mjesec besplatan“.","also":["hipoteze","hipotezu","hipotezom","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Eksperiment","text":"Mali planirani test da saznaš radi li neka ideja, prije nego što na nju uložiš puno.","also":["eksperimenti","eksperimenta","eksperimentu","pokus","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Dokaz koncepta (PoC)","text":"Brz, grub pokušaj da se vidi može li ideja uopće raditi. Obično se baci čim dobiješ odgovor.","also":["PoC","dokaz koncepta","dokaza koncepta","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototip","text":"Rani model proizvoda, često slike po kojima se može klikati, da ideju isprobaš na ljudima prije nego što je izgradiš kako treba.","also":["prototipi","prototipa","prototipu","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Skica zaslona (Wireframe)","text":"Jednostavna skica zaslona koja pokazuje gdje što stoji, bez boja i stvarnog sadržaja.","also":["skica zaslona","skice zaslona","žičani okvir","wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Mockup (maketa)","text":"Detaljna slika kako će zaslon izgledati, sa stvarnim bojama i tekstom, ali još ništa ne radi.","also":["maketa","makete","maketu","mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Poslovni slučaj (Business case)","text":"Razlozi za provedbu projekta: koliko košta, što donosi ili uštedi i koji su rizici.","also":["poslovni slučajevi","poslovnog slučaja","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Izvedivost","text":"Može li se nešto doista izgraditi i održavati s vremenom, novcem i vještinama koje imaš.","also":["izvedivosti","feasibility"]},{"id":"outcome","g":"idea","word":"Ishod (Outcome)","text":"Promjena koju želiš za ljude, na primjer manje propuštenih termina. Važnija je od toga koliko se toga izgradi.","also":["ishodi","ishoda","ishodu","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Izlaz (Output)","text":"Nešto što tim napravi, poput novog zaslona ili izvještaja. To što je napravljeno ne znači automatski da nekome pomaže.","also":["izlazi","izlaza","rezultat rada","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Mjera uspjeha","text":"Broj koji govori je li posao postigao svrhu, na primjer više ljudi koji dovrše narudžbu.","also":["mjere uspjeha","mjeru uspjeha","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Ključni pokazatelj uspješnosti (KPI)","text":"Važan broj koji pratiš da vidiš ide li dobro, na primjer broj registracija tjedno.","also":["KPI","KPI-jevi","KPI-ja","ključni pokazatelji","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Ciljevi i ključni rezultati (OKR)","text":"Način postavljanja ciljeva: cilj kaže što želiš, a nekoliko ključnih rezultata su brojevi koji pokazuju da je cilj postignut.","also":["OKR","OKR-ovi","OKR-a","ciljevi i ključni rezultati","OKRs","objectives and key results"]},{"id":"product","g":"plan","word":"Proizvod","text":"Ono što se gradi i održava za korisnike, poput aplikacije, web-stranice ili alata.","also":["proizvodi","proizvoda","proizvodu","proizvodom","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Vizija proizvoda","text":"Kratka izjava o tome kome proizvod pomaže i kamo ide dugoročno.","also":["izjava o viziji","vizije proizvoda","viziju proizvoda","vision statement","product vision"]},{"id":"po","g":"plan","word":"Vlasnik proizvoda (PO)","text":"Osoba koja odlučuje što će se graditi i kojim redom, da tim uvijek radi na onome što je najvažnije. U AI-gileu to si ti.","also":["PO","vlasnici proizvoda","vlasnika proizvoda","product owner","product owners"]},{"id":"pm","g":"plan","word":"Voditelj proizvoda (PM)","text":"Osoba koja brine o smjeru proizvoda: koje probleme rješava, za koga i zašto. PM može značiti i voditelj projekta, pa provjeri koje je od to dvoje.","also":["PM","voditelji proizvoda","voditelja proizvoda","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Voditelj projekta","text":"Osoba koja pazi da projekt ostane u roku i proračunu te prati tko što radi i do kada.","also":["voditelji projekata","voditelja projekta","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Plan razvoja (Roadmap)","text":"Grub plan onoga što dolazi idućih mjeseci, redom. Pokazuje smjer, a ne točne datume, i mijenja se kako učiš.","also":["plan razvoja","plana razvoja","roadmapa","roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Prekretnica (Milestone)","text":"Točka u projektu koju vrijedi označiti, poput „prva verzija uživo“ ili „100 korisnika“.","also":["prekretnice","prekretnicu","ključni događaj","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Minimalni održivi proizvod (MVP)","text":"Najmanja verzija proizvoda koja je ipak korisna stvarnim ljudima, da od njih možeš učiti što ranije.","also":["MVP","MVP-a","minimalni održivi proizvod","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Zahtjev","text":"Nešto što gotov proizvod mora raditi ili biti.","also":["zahtjevi","zahtjeva","zahtjevima","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Opseg (Scope)","text":"Što je uključeno u posao i, jednako važno, što nije.","also":["scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Širenje opsega (Scope creep)","text":"Kad se poslu malo-pomalo dodaje sve više, a da se nitko nije složio s dodatnim vremenom ili troškom, pa nikad baš ne završi.","also":["širenje opsega","širenja opsega","puzanje opsega","scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Značajka (Feature)","text":"Jedna stvar koju proizvod može napraviti za ljude, poput „ponovno postavi lozinku“.","also":["značajke","značajku","značajki","funkcija","funkcije","mogućnost","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Velik dio posla, prevelik da se napravi odjednom, pa se dijeli na manje kartice.","also":["epici","epica","epicu","epic","epics"]},{"id":"story","g":"plan","word":"Korisnička priča (User story)","text":"Mali dio posla napisan iz korisnikove perspektive: „Kao kupac želim spremiti svoju košaricu da je mogu dovršiti kasnije.“ Pokreće razgovor o tome što izgraditi.","also":["korisničke priče","korisničku priču","korisničkih priča","user story","user stories"]},{"id":"ac","g":"plan","word":"Kriteriji prihvaćanja (AC)","text":"Provjere koje jedna kartica mora proći da bi se smatrala gotovom, dogovorene prije početka rada, poput „košarica je još tu nakon što se odjavim i ponovno prijavim“.","also":["AC","kriteriji prihvaćanja","kriterija prihvaćanja","acceptance criteria"]},{"id":"task","g":"plan","word":"Zadatak","text":"Jedan pojedinačni posao, često mali korak veće priče.","also":["zadaci","zadatka","zadatku","zadataka","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiket (Ticket)","text":"Druga riječ za karticu: jedan dio posla ili jedan zahtjev, praćen od početka do kraja.","also":["tiketi","tiketa","tiketu","ticket","tickets"]},{"id":"priority","g":"plan","word":"Prioritet","text":"Koliko je nešto važno ili hitno u usporedbi sa svime ostalim, da se najvažniji posao radi prvi.","also":["prioriteti","prioriteta","prioritetu","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Određivanje prioriteta","text":"Slaganje posla po važnosti. Čest način je MoSCoW: Must (mora), Should (trebalo bi), Could (moglo bi), Won’t (ne ovaj put).","also":["prioritiziranje","određivanje prioriteta","prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"Procjena","text":"Najbolja pretpostavka koliko je neki posao velik ili koliko traje. To je pretpostavka, a ne obećanje.","also":["procjene","procjenu","procjenjivanje","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Bodovi priče (Story points)","text":"Način procjene veličine posla uspoređivanjem kartica jedne s drugima („otprilike dvostruko veća od one“), a ne u satima. Nisu za uspoređivanje timova.","also":["bodovi priče","bodova priče","storypointovi","story point","story points"]},{"id":"tshirt","g":"plan","word":"Veličine majica (T-shirt sizing)","text":"Procjena veličine posla kao S, M, L ili XL. Brzo je i dovoljno dobro za rano planiranje.","also":["veličine majica","S M L XL","t-shirt sizes","t-shirt sizing"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Igra za procjenjivanje: svi istodobno pokažu kartu s veličinom, a zatim najviša i najniža procjena objasne zašto.","also":["Scrum poker","poker za procjenu","planning poker"]},{"id":"dependency","g":"plan","word":"Ovisnost","text":"Kad jedan posao ne može početi ili završiti dok ne počne ili završi drugi.","also":["dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Prepreka (Blocker)","text":"Sve što trenutačno zaustavlja napredak posla, poput odgovora koji nedostaje ili pokvarenog alata.","also":["blocker","blockers"]},{"id":"deadline","g":"plan","word":"Rok","text":"Datum do kojeg nešto mora biti gotovo.","also":["rokovi","roka","roku","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Isporuka (Deliverable)","text":"Nešto konkretno što posao proizvede i preda, poput stranice koja radi ili izvještaja.","also":["isporučevina","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Prognoza","text":"Predviđanje što će se vjerojatno dogoditi, na primjer kad će posao biti gotov, na temelju onoga što do sada znaš.","also":["prognoze","prognozu","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metrika","text":"Sve što mjeriš i pratiš kroz vrijeme, poput posjeta stranici ili trajanja popravka.","also":["metrike","metriku","metric","metrics"]},{"id":"feedback","g":"plan","word":"Povratna informacija","text":"Što ti ljudi kažu o tvom radu, dobro i loše. Dobivati je rano i često srž je Agilea.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Popis čekanja za ideje i posao koji još nije planiran, s najvažnijim na vrhu. Ništa se odatle ne radi dok se ne premjesti u „Na redu“."},{"id":"sprint","g":"agile","word":"Sprint","text":"Kratko, fiksno razdoblje rada (često jedan ili dva tjedna, nikad dulje od mjesec dana) s ciljem i dogovorenim skupom kartica za dovršiti.","also":["sprintovi","sprinta","sprintu","sprintom","sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Brza svakodnevna provjera: što je tko u timu napravio, što radi dalje i što ga koči. U Scrumu se zove dnevni scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","dnevni scrum","dnevni sastanak"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Način rada u kojem se kartice kreću kroz stupce ploče (poput Na redu, U tijeku, Gotovo), a tim ograničava koliko je odjednom u tijeku, pa posao stalno teče."},{"id":"wip","g":"agile","word":"WIP ograničenje","text":"WIP je kratica za work in progress (posao u tijeku). WIP limit je najveći broj kartica koje stupac smije imati odjednom, da tim završava stvari prije nego počne nove.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definicija gotovosti","text":"Kratak timski popis onoga što znači „gotovo”, npr. testirano i objašnjeno, prije nego što ti se kartica preda. Njezina blizanka, Definicija spremnosti, kaže kad je kartica dovoljno jasna da se počne.","also":["Definition of Ready","DoD","DoR","definicija spremnosti"]},{"id":"retro","g":"agile","word":"Retro","text":"Redovit pogled unatrag na to kako tim radi, da se dogovore jedna-dvije stvari koje će sljedeći put biti bolje. Skraćeno od retrospektiva. U AI-gileu retro predlaže promjenu načina rada tima, a ti kažeš Go ili Još ne.","also":["retrospektiva","retrospektive","retros"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Svi na okup: mnogo ljudi ostavi drugi posao da zajedno riješe jednu hitnu stvar dok se ne sredi. U AI-gileu svi timovi pomažu na jednom projektu, a ostali projekti u međuvremenu čekaju.","also":["swarming","roj"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"U Scrumu osoba koja pomaže timu da dobro radi: uklanja ono što ga koči, pazi da sastanci ne skreću s teme i potiče dobre navike, bez zapovijedanja. U AI-gileu Lead Scrum Master uočava zapele kartice, potiče timove i podsjeća te na ono što čeka, u svim projektima.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (agilni pristup)","text":"Način rada u malim koracima: izgradiš malo, često pokažeš stvarne rezultate, učiš iz onoga što ljudi kažu i mijenjaš plan usput, umjesto da sve planiraš unaprijed.","also":["agilno","agilni razvoj","agilni pristup","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agilni manifest","text":"Kratka izjava koju su 2001. napisali izrađivači softvera. Ljude, rezultate koji rade, blisku suradnju s korisnicima i prilagođavanje promjenama stavlja ispred teških planova i papirologije.","also":["Agilni manifest","Agilnog manifesta","Agile manifest","Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Vodopad (Waterfall)","text":"Stariji način rada: sve isplaniraš, zatim sve izgradiš, zatim sve testiraš, jedna faza za drugom. Kasne promjene su teške i skupe.","also":["model vodopada","vodopadni model","waterfall","waterfall model"]},{"id":"iteration","g":"agile","word":"Iteracija","text":"Jedan krug građenja nečega, provjere i poboljšanja. Agilni rad je niz takvih krugova, a sprint je jedna vrsta.","also":["iteracije","iteraciju","iteraciji","iteration","iterations"]},{"id":"increment","g":"agile","word":"Inkrement","text":"Novi dio koji radi, dodan proizvodu u sprintu ili krugu rada, a uklapa se u ono što je već bilo.","also":["inkrementi","inkrementa","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Popularan agilni način rada: mali tim radi u kratkim sprintovima prema cilju, s utvrđenim ulogama i nekoliko redovitih sastanaka za planiranje, provjeru i poboljšanje."},{"id":"scrumteam","g":"agile","word":"Scrum tim","text":"Mala skupina koja radi posao u Scrumu: vlasnik proizvoda, Scrum Master i programeri.","also":["Scrum timovi","Scrum tima","Scrum timu","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum događaji","text":"Redoviti sastanci u Scrumu: planiranje sprinta, dnevni scrum, pregled sprinta i retrospektiva. Mnogi ih zovu ceremonijama.","also":["ceremonije","Scrum ceremonije","Scrum događaji","Scrum događaja","ceremonies","Scrum ceremonies","Scrum events"]},{"id":"sprintplan","g":"agile","word":"Planiranje sprinta","text":"Sastanak na početku sprinta na kojem se tim dogovara zašto je sprint važan, koje će kartice preuzeti i kako početi.","also":["sastanak za planiranje","planiranja sprinta","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Cilj sprinta","text":"Jedna rečenica o tome čemu sprint služi. Sitni zadaci se usput mogu mijenjati, sve dok je cilj postignut.","also":["ciljevi sprinta","cilja sprinta","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog (popis sprinta)","text":"Kartice odabrane za trenutni sprint, s planom tima kako ih odraditi.","also":["popis sprinta","sprint backloga","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog (popis proizvoda)","text":"Cijeli poredani popis svega što bi se moglo izgraditi za proizvod, s najvažnijim na vrhu. Stalno se mijenja kako učiš.","also":["popis proizvoda","product backloga","product backlogs"]},{"id":"productgoal","g":"agile","word":"Cilj proizvoda","text":"Veći rezultat prema kojem proizvod ide i koji timu pomaže izabrati što dalje raditi.","also":["ciljevi proizvoda","cilja proizvoda","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Dorada backloga (Refinement)","text":"Redovito prolaženje kroz backlog da se kartice počiste, podijele, poredaju i dopune detaljima, kako bi bile spremne za preuzimanje. Zove se i backlog grooming.","also":["dorada backloga","uređivanje backloga","refinement","backlog grooming"]},{"id":"sprintreview","g":"agile","word":"Pregled sprinta","text":"Sastanak na kraju sprinta na kojem tim pokazuje što je dovršio i čuje što ljudi misle, da odluči što slijedi.","also":["pregledi sprinta","pregleda sprinta","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Pokazivanje gotovog posla na djelu, uživo, ljudima koji su ga tražili.","also":["demoi","demoa","demonstracija","demonstracije","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Vremenski okvir (Timebox)","text":"Unaprijed zadano vrijeme za nešto. Kad istekne, staje se, čak i ako nije sve gotovo.","also":["vremenski okvir","vremenskog okvira","ograničeno vremenom","timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Brzina tima (Velocity)","text":"Koliko posla tim obično dovrši u sprintu, a koristi se za planiranje koliko preuzeti idući put. Nije ocjena koliko se naporno radi.","also":["brzina tima","brzine tima","velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Kapacitet","text":"Koliko posla tim može preuzeti u nekom razdoblju, nakon odbitka godišnjih odmora i drugih obveza.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown grafikon","text":"Grafikon preostalog posla u sprintu koji pada iz dana u dan. Ako linija stoji ravno, nešto je zapelo.","also":["burndown","burndown grafikona","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Burnup grafikon","text":"Grafikon dovršenog posla koji raste kroz vrijeme, uz ukupno planirano, da vidiš kada ćeš stići.","also":["burnup","burnup grafikona","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban ploča","text":"Sama ploča: stupac za svaku fazu posla, s karticama koje putuju naprijed.","also":["kanban ploče","kanban ploču","kanban ploči","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Sustav povlačenja (Pull system)","text":"Način rada u kojem novi posao počinje tek kad netko ima mjesta da ga preuzme, umjesto da ga se gura na već pun tanjur.","also":["sustav povlačenja","pull system","pull-based"]},{"id":"flow","g":"agile","word":"Tok (Flow)","text":"Koliko glatko posao putuje po ploči. Dobar tok znači da se kartice kreću, a ne gomilaju.","also":["tok posla","toka","toku","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Ukupno vrijeme (Lead time)","text":"Koliko prođe od trenutka kad netko nešto zatraži do trenutka kad je gotovo.","also":["vrijeme isporuke","lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Vrijeme rada (Cycle time)","text":"Koliko kartici treba od trenutka kad se na njoj doista počne raditi do kraja.","also":["cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Propusnost (Throughput)","text":"Koliko se kartica dovrši tjedno ili u bilo kojem zadanom vremenu.","also":["propusnost","protočnost","throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Usko grlo (Bottleneck)","text":"Jedna faza u kojoj se posao gomila i usporava sve iza nje, kao uski vrat boce.","also":["usko grlo","uska grla","uskog grla","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Traka (Swimlane)","text":"Redak kroz ploču koji grupira kartice jedne vrste, poput hitnog posla ili kartica jednog tima.","also":["swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean (vitki pristup)","text":"Način rada koji izbacuje gubitke (sve što ne pomaže korisniku) i održava tok posla."},{"id":"waste","g":"agile","word":"Gubitak (Waste)","text":"U Leanu sve što troši trud, a ne pomaže korisniku, poput čekanja, prepravljanja ili izrade stvari koje nitko ne koristi.","noTip":1},{"id":"kaizen","g":"agile","word":"Kontinuirano poboljšanje","text":"Stalno postajati malo bolji kroz male redovite promjene, a zatim provjeriti jesu li pomogle. Retrospektive su jedan od načina. Zove se i kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Samoorganizirani tim","text":"Tim koji sam odlučuje kako će raditi posao, umjesto da mu se govori korak po korak.","also":["samoorganizirani","samoorganizirani timovi","self-organising","self-organising team","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Multifunkcionalni tim","text":"Tim koji ima sve vještine potrebne da sam dovrši posao, poput dizajna, izrade i testiranja.","also":["multifunkcionalni","međufunkcionalni tim","cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Istraživački zadatak (Spike)","text":"Kratko istraživanje ograničeno vremenom koje odgovara na pitanje prije nego što se upustiš u pravi posao.","also":["istraživački zadatak","spike","spikes"]},{"id":"rework","g":"agile","word":"Prepravljanje (Rework)","text":"Ponovno obavljanje posla jer prvi put nije bio dobar.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Skalirani Agile (SAFe)","text":"Načini korištenja Agilea u mnogo timova velike organizacije. SAFe (Scaled Agile Framework) je jedan poznat primjer.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Projektna mapa s kodom i cijelom poviješću commitova. Može biti na tvom računalu, na GitHubu ili na oba mjesta.","also":["repozitorij","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Zasebna linija rada u kodu, da se izmjene mogu raditi bez diranja glavne verzije.","also":["branchevi","grana","grane","branches"]},{"id":"commit","g":"build","word":"Commit","text":"Spremljena snimka koda s kratkom bilješkom o tome što se promijenilo. Uvijek se možeš vratiti na neku.","also":["commitovi","commita","commitu","commits"]},{"id":"push","g":"build","word":"Push","text":"Slanje tvojih spremljenih snimaka (commitova) s ovog računala u zajedničku kopiju na internetu, poput GitHuba, da budu sigurnosno kopirani i da ih drugi mogu dohvatiti."},{"id":"merge","g":"build","word":"Merge","text":"Spajanje promjena iz jedne grane u drugu, obično natrag u glavnu verziju."},{"id":"pr","g":"build","word":"Pull request","text":"Traženje da se promjene jedne grane provjere i spoje u glavnu verziju. Neke stranice to zovu merge request.","also":["PR","PRs","merge request","zahtjev za spajanje"]},{"id":"refactor","g":"build","word":"Refaktoriranje","text":"Uređivanje koda bez mijenjanja onoga što radi: manje datoteke, jasniji nazivi, manje ponavljanja."},{"id":"bug","g":"build","word":"Bug","text":"Nešto što ne radi onako kako bi trebalo.","also":["bugovi","buga","bugu","bugs"]},{"id":"peerreview","g":"build","word":"Recenzija kolege","text":"Drugi par očiju: netko drugi, a ne autor, provjerava rad prije nego stigne do tebe, pa prođe manje grešaka. U AI-gileu svaku karticu provjerava drugi AI.","also":["peer review","code review","pregled koda"]},{"id":"code","g":"build","word":"Kod","text":"Napisane upute koje računalu govore što da radi. Zove se i izvorni kod.","also":["izvorni kod","koda","kodu","source code","code"],"noTip":1},{"id":"proglang","g":"build","word":"Programski jezik","text":"Jezik za pisanje koda, poput JavaScripta, Pythona ili Jave. Različiti jezici odgovaraju različitim poslovima.","also":["programski jezici","programskog jezika","programming language","programming languages"]},{"id":"developer","g":"build","word":"Programer (dev)","text":"Osoba koja piše i mijenja kod. Zove se i programer ili softverski inženjer.","also":["programeri","programera","programerima","razvojni inženjer","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Softver","text":"Programi koji rade na računalima i telefonima, za razliku od samih strojeva (hardvera).","noTip":1},{"id":"app","g":"build","word":"Aplikacija (App)","text":"Program koji ljudi koriste da nešto obave, na telefonu, računalu ili u web-pregledniku.","also":["aplikacije","aplikaciju","aplikaciji","app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web-aplikacija","text":"Aplikacija koja radi u web-pregledniku, pa ništa ne treba instalirati.","also":["web-aplikacije","web-aplikaciju","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Front end (prednji dio)","text":"Dio aplikacije koji vidiš i na koji klikaš: zasloni, gumbi i riječi, često u tvom pregledniku.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end (stražnji dio)","text":"Dio aplikacije iza kulisa koji čuva podatke i radi posao kad nešto klikneš, na primjer provjerava tvoju lozinku.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack (cjelovit razvoj)","text":"Rad i na prednjem i na stražnjem dijelu.","also":["full-stack","full stack"]},{"id":"ui","g":"build","word":"Korisničko sučelje (UI)","text":"Ono što osoba vidi i koristi na zaslonu: raspored, gumbi, izbornici i tekst.","also":["UI","korisničko sučelje","user interface"]},{"id":"ux","g":"build","word":"Korisničko iskustvo (UX)","text":"Kakav je osjećaj koristiti nešto: lako, jasno i ugodno ili zbunjujuće i sporo.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Pristupačnost (a11y)","text":"Izrada stvari koje svatko može koristiti, uključujući ljude koji slabo vide, ne mogu koristiti miš ili se služe čitačem zaslona.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Responzivni dizajn","text":"Stranice se prilagođavaju i dobro rade na svakoj veličini zaslona, od telefona do velikog monitora.","also":["responsive design","prilagodljiv dizajn"]},{"id":"designsys","g":"build","word":"Dizajnerski sustav","text":"Zajednički komplet boja, fontova, gumba i pravila, da svaki zaslon izgleda i ponaša se jednako.","also":["dizajnerski sustavi","dizajnerskog sustava","design system","design systems"]},{"id":"architecture","g":"build","word":"Arhitektura","text":"Cjelokupan oblik sustava: koji su glavni dijelovi i kako međusobno razgovaraju."},{"id":"database","g":"build","word":"Baza podataka (DB)","text":"Uredna pohrana informacija, poput vrlo moćne proračunske tablice koju aplikacija može čitati i mijenjati.","also":["baze podataka","bazu podataka","bazi podataka","database","databases","DB"]},{"id":"schema","g":"build","word":"Shema baze podataka","text":"Raspored baze podataka: koje tablice informacija ima i što ide u svaku.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Kratica za structured query language (strukturirani jezik upita): jezik kojim se od mnogih baza podataka traže informacije ili ih se mijenja.","also":["Structured Query Language","jezik upita"]},{"id":"data","g":"build","word":"Podaci","text":"Informacije koje čuva računalo, poput imena, narudžbi ili postavki.","also":["data","dataset","datasets","skup podataka"],"noTip":1},{"id":"server","g":"build","word":"Poslužitelj (Server)","text":"Računalo koje je uvijek uključeno i odgovara na zahtjeve drugih računala, na primjer šalje web-stranicu kad je posjetiš.","also":["poslužitelji","poslužitelja","poslužitelju","serveri","servera","server","servers"]},{"id":"client","g":"build","word":"Klijent","text":"Strana koja nešto traži, obično tvoj preglednik ili aplikacija, a razgovara s poslužiteljem. U poslovnom svijetu znači i jednostavno kupca.","also":["klijenti","klijenta","klijentu","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Kratica za application programming interface (programsko sučelje aplikacije): stalni jelovnik zahtjeva koje jedan program može poslati drugom, na primjer da od vremenske službe zatraži današnju prognozu.","also":["API-ja","API-ju","programsko sučelje","APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Krajnja točka (Endpoint)","text":"Jedna stavka na jelovniku API-ja: web-adresa koju program može pozvati da nešto dobije ili pošalje.","also":["krajnje točke","krajnju točku","endpoint","endpoints"]},{"id":"integration","g":"build","word":"Integracija","text":"Povezivanje dvaju sustava da rade zajedno, na primjer kad tvoja web-trgovina šalje narudžbe u računovodstveni program.","also":["integracije","integraciju","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Poruka koju jedan sustav sam pošalje drugome u trenutku kad se nešto dogodi, na primjer „uplata primljena“.","also":["webhooka","webhookovi","webhooks"]},{"id":"library","g":"build","word":"Biblioteka","text":"Gotov kod koji je netko drugi napisao i koji možeš ponovno upotrijebiti umjesto da ga pišeš od nule.","also":["biblioteke","biblioteku","knjižnica","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Okvir (Framework)","text":"Gotova struktura za izradu aplikacije koja određuje velik dio rasporeda koda, poput okvira kuće koji ti popunjavaš.","also":["frameworka","framework","frameworks"]},{"id":"sdk","g":"build","word":"Razvojni komplet (SDK)","text":"Kutija alata, koda i primjera za izradu softvera za jednu platformu ili uslugu.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Softverska ovisnost","text":"Biblioteka ili alat koji tvom kodu treba da bi radio. Važno ih je održavati ažurnima zbog sigurnosti.","also":["softverske ovisnosti","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Paket","text":"Svežanj gotovog koda koji možeš instalirati i koristiti u projektu.","also":["paketi","paketa","paketu","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Upravitelj paketa","text":"Alat koji dohvaća i ažurira pakete o kojima tvoj kod ovisi. npm je čest.","also":["upravitelji paketa","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Najrašireniji alat za čuvanje povijesti promjena koda, u obliku commitova i grana (branchova)."},{"id":"github","g":"build","word":"GitHub","text":"Web-stranica koja čuva Git repozitorije na internetu, da timovi mogu dijeliti kod, pregledavati promjene i pratiti posao."},{"id":"vcs","g":"build","word":"Kontrola verzija","text":"Čuvanje cjelovite povijesti svake promjene datoteka, da vidiš tko je što promijenio i da se možeš vratiti. Git to radi.","also":["kontrola verzija","kontrole verzija","kontrola izvornog koda","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Kloniranje (Clone)","text":"Izrada vlastite potpune kopije repozitorija, s poviješću, na tvom računalu.","also":["kloniranje","kloniraj","klonirati","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Povlačenje (Pull)","text":"Dohvaćanje najnovijih commitova iz zajedničke kopije (poput GitHuba) na tvoje računalo. Suprotno od push.","also":["povlačenje","git pull","pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Glavna grana (Main branch)","text":"Službena verzija koda od koje svi polaze, često zvana main ili master.","also":["glavna grana","glavne grane","glavnoj grani","main","master","main branch","master branch"]},{"id":"conflict","g":"build","word":"Konflikt pri spajanju","text":"Kad dvije promjene dotiču iste retke na različite načine, pa ih računalo ne može spojiti i osoba mora izabrati.","also":["konflikti pri spajanju","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Razlika (Diff)","text":"Prikaz koji točno pokazuje što se promijenilo između dviju verzija: dodani i uklonjeni retci.","also":["diff","diffs"]},{"id":"fork","g":"build","word":"Račvanje (Fork)","text":"Tvoja vlastita kopija tuđeg repozitorija koju možeš mijenjati bez utjecaja na izvornik.","also":["račvanje","forka","fork","forks","forked"]},{"id":"script","g":"build","word":"Skripta","text":"Kratak program koji sam obavlja jedan posao, poput sređivanja datoteka ili pokretanja aplikacije.","also":["skripte","skriptu","skripti","script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Izgradnja (Build)","text":"Pretvaranje koda u nešto spremno za pokretanje ili sam rezultat spreman za pokretanje.","also":["izgradnja","izgradnje","buildovi","builda","build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompajliranje","text":"Prevođenje koda koji su napisali ljudi u oblik koji računalo može izravno izvršiti.","also":["kompajliranje","kompajler","kompajlirati","compile","compiler"]},{"id":"cli","g":"build","word":"Naredbeni redak (CLI)","text":"Tekstni prozor u koji računalu upisuješ upute umjesto da klikaš. Zove se i terminal.","also":["naredbeni redak","naredbenog retka","terminal","terminala","command line","command-line","CLI"]},{"id":"config","g":"build","word":"Konfiguracija (config)","text":"Postavke koje određuju kako se softver ponaša, čuvane odvojeno od koda da ih je lako mijenjati.","also":["konfiguracija","konfiguracije","postavke","config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Varijabla okruženja","text":"Postavka predana programu pri pokretanju, često za adrese ili lozinke, da ne budu upisane u kod.","also":["varijable okruženja","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Otklanjanje grešaka (debugging)","text":"Traženje razloga zašto nešto ne radi i njegovo popravljanje.","also":["otklanjanje grešaka","debugiranje","debugirati","debugging","debug","debugged"]},{"id":"pairing","g":"build","word":"Programiranje u paru","text":"Dvije osobe (ili osoba i AI) rade zajedno na istom kodu, jedna tipka, a druga provjerava.","also":["rad u paru","programiranje u paru","pair programming","pairing"]},{"id":"docs","g":"build","word":"Dokumentacija (docs)","text":"Napisana objašnjenja kako nešto radi ili kako se koristi.","also":["dokumentacija","dokumentacije","dokumenti","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Prva datoteka koju treba pročitati u repozitoriju: što je projekt i kako ga pokrenuti.","also":["README-a","pročitaj me","READMEs"]},{"id":"legacy","g":"build","word":"Naslijeđeni sustav (Legacy)","text":"Stariji sustav koji se još koristi, a teško ga je mijenjati, često zato što ga malo ljudi još razumije.","also":["naslijeđeni sustavi","naslijeđeni kod","naslijeđenog koda","legacy","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Tehnički dug","text":"Prečaci koji sada štede vrijeme, ali kasnije promjene čine sporijima, poput zajma na koji raste kamata. Refaktoriranje ga otplaćuje.","also":["tehnički dugovi","tehničkog duga","tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"Provjera radi li nešto kako treba. Neke testove računalo samo pokreće pri svakoj promjeni koda; druge radiš ti kad isprobavaš gotovu karticu prije nego što je prihvatiš.","also":["testovi","testirati","testiranje","testiraš","testiraj","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kratica za quality assurance (osiguranje kvalitete): sve što se radi da posao bude ispravan prije nego krene uživo. U AI-gileu to su automatske provjere: kad je QA crven, nešto nije prošlo i ne može ići uživo dok se to ne popravi.","also":["provjere kvalitete","quality checks"]},{"id":"testpile","g":"test","word":"Hrpa za testiranje","text":"Gotove kartice koje čekaju da ih isprobaš, jednu za drugom. Prihvati jednu ili je vrati s napomenom, i dolazi sljedeća.","also":["hrpe za testiranje","test pile"]},{"id":"autotest","g":"test","word":"Automatski test","text":"Provjera koju računalo samo pokreće pri svakoj promjeni koda, da se greške uhvate rano.","also":["automatski testovi","automatskih testova","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Ručni test","text":"Osoba ručno isprobava rad da vidi ponaša li se kako treba.","also":["ručni testovi","ručno testiranje","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Jedinični test (Unit test)","text":"Mala automatska provjera jednog malog dijela koda, zasebno.","also":["jedinični testovi","jediničnih testova","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Integracijski test","text":"Provjera da nekoliko dijelova dobro radi zajedno, a ne samo svaki za sebe.","also":["integracijski testovi","integracijskih testova","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Test od kraja do kraja (E2E)","text":"Test koji se ponaša kao pravi korisnik od početka do kraja, na primjer registrira se, kupuje i plaća.","also":["E2E","test od kraja do kraja","end-to-end test","end-to-end tests"]},{"id":"uat","g":"test","word":"Korisničko prihvatno testiranje (UAT)","text":"Ljudi koji su zatražili posao sami ga isprobavaju i kažu radi li što im treba. Hrpa za testiranje u AI-gileu njegova je verzija toga.","also":["UAT","prihvatno testiranje","korisničko testiranje","acceptance testing"]},{"id":"regression","g":"test","word":"Regresija","text":"Nešto što je radilo, a pokvarilo se nakon promjene. Regresijski testovi provjeravaju rade li stare stvari još.","also":["regresije","regresiju","regresijski testovi","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Brzi probni test (Smoke test)","text":"Vrlo brza provjera radi li glavno uopće, na primjer odmah nakon što promjena krene uživo. Ako ne prođe, stani i pogledaj.","also":["brzi probni test","smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Istraživačko testiranje","text":"Slobodno isprobavanje proizvoda i bockanje na različite načine, da se nađu problemi koje bi planirane provjere propustile.","also":["istraživačko testiranje","istraživačkog testiranja","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Testni slučaj","text":"Jedan zapisani scenarij za isprobavanje: koraci i što bi se trebalo dogoditi.","also":["testni slučajevi","testnog slučaja","test case","test cases"]},{"id":"coverage","g":"test","word":"Pokrivenost testovima","text":"Koliki dio koda provjeravaju automatski testovi. Više je obično sigurnije, ali sama visoka pokrivenost ne dokazuje da sve dobro radi.","also":["pokrivenost koda","test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Testni podaci","text":"Izmišljeni primjeri podataka koji se koriste pri testiranju, da se ne otkriju privatni podaci stvarnih ljudi.","also":["testni podaci","testnih podataka","test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Rubni slučaj (Edge case)","text":"Neobična situacija na granici, poput praznog obrasca ili imena s apostrofom, gdje se stvari često kvare.","also":["rubni slučajevi","rubnog slučaja","rubnih slučajeva","edge case","edge cases"]},{"id":"happypath","g":"test","word":"Sretan put (Happy path)","text":"Uobičajen put kad sve ide kako treba. Dobro testiranje isprobava i nesretne putove."},{"id":"perftest","g":"test","word":"Testiranje performansi","text":"Provjera koliko je nešto brzo i kako se nosi s opterećenjem.","also":["testiranje performansi","test performansi","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Testiranje opterećenja","text":"Provjera kako se sustav nosi kad ga mnogo ljudi koristi istodobno.","also":["testiranje opterećenja","test opterećenja","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Sigurnosno testiranje","text":"Traženje slabosti kojima bi netko mogao zloupotrijebiti sustav ili vidjeti ono što ne bi smio.","also":["sigurnosno testiranje","sigurnosni test","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Testiranje pristupačnosti","text":"Provjera mogu li ljudi različitih sposobnosti koristiti proizvod, uključujući s čitačem zaslona ili samo tipkovnicom.","also":["testiranje pristupačnosti","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Lintanje (Linting)","text":"Automatska provjera koja uočava vjerojatne greške i neuredan stil u kodu, poput provjere pravopisa za programe.","also":["lintanje","linter","lintera","linting","lint"]},{"id":"static","g":"test","word":"Statička analiza","text":"Automatsko pregledavanje koda u potrazi za problemima, bez njegova pokretanja.","also":["static analysis","static code analysis","statička analiza koda"]},{"id":"flaky","g":"test","word":"Nestabilan test (Flaky test)","text":"Test koji ponekad prođe, a ponekad padne bez jasnog razloga, pa mu se ne može posve vjerovati.","also":["nestabilni testovi","nepouzdan test","flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Reproduciranje (repro)","text":"Namjerno ponovno izazivanje buga istim koracima, da se može proučiti i popraviti. Zapisivanje tih koraka najkorisniji je dio prijave buga.","also":["repro","reproduce","steps to reproduce","koraci za reproduciranje"]},{"id":"severity","g":"test","word":"Ozbiljnost (Severity)","text":"Koliko je loš učinak problema, od sitne smetnje do zastoja svega.","also":["razina ozbiljnosti","severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Kopiranje nove verzije softvera na računala koja ga pokreću, poput testne kopije ili usluge uživo."},{"id":"release","g":"change","word":"Izdanje","text":"Imenovani paket završenog rada koji ide uživo zajedno, s kratkim bilješkama o tome što se promijenilo. 🚀 Izdanja pišu bilješke iz gotovih kartica.","also":["izdanja","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Povratak na posljednju verziju koja je radila kad nova stvara probleme. U AI-gileu „Vrati unatrag“ skuplja korake poništavanja zapisane uz svaku promjenu u jedan kontrolni popis.","also":["roll back","vraćanje na staro"]},{"id":"live","g":"change","word":"Uživo","text":"Prava verzija koju ljudi koriste, za razliku od kopije za isprobavanje. Programeri je zovu i produkcija.","also":["produkcija","production","live"],"noTip":1},{"id":"change","g":"change","word":"Promjena","text":"Planirana promjena nečega o čemu ljudi ovise, unaprijed zapisana: što, zašto, rizik, kada i kako je poništiti. Pokreni je s 🔀 Podnesi promjenu.","also":["promjene","zahtjev za promjenu","change request"],"noTip":1},{"id":"risk","g":"change","word":"Rizik","text":"Nešto što bi moglo poći po zlu, ocijenjeno prema tome koliko je vjerojatno i koliko bi bilo loše. ⚠️ Rizici ih drže na jednom popisu, s najvišom ocjenom na vrhu, svaki s datumom za ponovni pregled.","also":["rizici","registar rizika","risk register"]},{"id":"chgwin","g":"change","word":"Prozor promjena","text":"Vrijeme kad promjene smiju ići uživo, npr. miran utorak navečer. Izvan prozora kartica promjene ne može se završiti, osim ako je hitno.","also":["prozori promjena","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Posljednja provjera tik prije nego promjena krene uživo: svaka osoba koja mora odobriti kaže Go ili No go. Nastavlja se samo kad svi kažu Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Odobrenje","text":"Čekanje na „da” prije početka rada. Kartica koju podnese prijatelj, ili promjena, čeka u ✅ Odobrenja dok je ne odobriš ili odbiješ.","also":["odobrenja","approval"]},{"id":"quiettime","g":"change","word":"Mirno razdoblje","text":"Razdoblje, na primjer tijekom prijenosa uživo, demoa ili preko noći, kad ništa ne ide uživo. Timovi i dalje rade i testiraju, ali puštanje uživo čeka kraj. Drugdje se zove zamrzavanje promjena.","also":["mirna razdoblja","zamrzavanje promjena","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Način rada u kojem ljudi koji grade softver i ljudi koji ga pokreću rade kao jedan tim, uz mnogo automatizacije, pa promjene idu uživo često i sigurno."},{"id":"cicd","g":"change","word":"CI/CD (kontinuirana integracija i isporuka)","text":"Promjene svih često se spajaju u glavnu verziju i svaki put automatski provjeravaju (kontinuirana integracija), pa je softver uvijek spreman za puštanje uživo na pritisak gumba (kontinuirana isporuka).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","kontinuirana integracija"]},{"id":"contdeploy","g":"change","word":"Kontinuirano postavljanje","text":"Korak dalje od kontinuirane isporuke: svaka promjena koja prođe provjere ide uživo sama, bez gumba za pritisnuti.","also":["kontinuirano postavljanje","kontinuirani deployment","automatsko postavljanje","continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Cjevovod (Pipeline)","text":"Automatski niz koraka kroz koje promjena prolazi na putu uživo, poput izgradnje, testa i postavljanja.","also":["cjevovod","cjevovodi","pipelinea","pipeline","pipelines"]},{"id":"environment","g":"change","word":"Okruženje (Environment)","text":"Jedna zasebna kopija sustava za jednu svrhu, na primjer jedna za razvoj, jedna za testiranje i ona uživo.","also":["okruženja","okruženju","okolina","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Razvojno okruženje","text":"Kopija u kojoj programer radi, često na vlastitom računalu, gdje kvarenje stvari nikome ne šteti.","also":["dev environment","development environment","dev okruženje"]},{"id":"testenv","g":"change","word":"Testno okruženje","text":"Zasebna kopija sustava koja se koristi samo za testiranje, da se prava usluga ne dira.","also":["testna okruženja","testnom okruženju","test environment","test environments"]},{"id":"staging","g":"change","word":"Pripremno okruženje (Staging)","text":"Posljednja kopija postavljena točno kao ona uživo, za završnu provjeru prije nego što promjena krene uživo.","also":["pripremno okruženje","staging okruženje","staging","staging environment"]},{"id":"artifact","g":"change","word":"Artefakt izgradnje","text":"Datoteka ili paket koji izgradnja proizvede, spremni da se pohrane, provjere ili puste uživo.","also":["build artifact","build artifacts","artefakt","artefakti"]},{"id":"hotfix","g":"change","word":"Hitni popravak (Hotfix)","text":"Hitan popravak pušten brzo, izvan uobičajenog plana, jer je nešto važno pokvareno.","also":["hitni popravak","hitni popravci","hotfix","hotfixes"]},{"id":"patch","g":"change","word":"Zakrpa (Patch)","text":"Malo ažuriranje koje popravlja bug ili zatvara sigurnosnu rupu. Sigurnosne zakrpe važno je brzo primijeniti.","also":["zakrpe","zakrpu","sigurnosne zakrpe","patch","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Broj verzije","text":"Oznaka poput 2.4.1 koja govori koju verziju imaš. Često se prvi broj mijenja kod velikih promjena, a zadnji kod sitnih popravaka.","also":["brojevi verzija","broja verzije","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Bilješke o izdanju","text":"Kratak običan popis što se promijenilo u izdanju, za ljude koji ga koriste, uključujući popravke i poznata ograničenja. Zove se i changelog.","also":["bilješke o izdanju","popis promjena","release notes","changelog","change log"]},{"id":"flag","g":"change","word":"Prekidač funkcije (Feature flag)","text":"Prekidač za uključivanje i isključivanje funkcije, da nov posao može ići uživo skriven pa se uključiti (ili opet isključiti) bez novog izdanja.","also":["prekidač funkcije","prekidači funkcija","zastavica funkcije","feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Popravak naprijed (Roll forward)","text":"Ispravljanje lošeg izdanja brzim puštanjem nove, ispravljene verzije umjesto povratka na staru.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary izdanje","text":"Prvo puštanje promjene za malu skupinu, a za sve tek kad izgleda u redu. Ime dolazi od kanarinaca koje su rudari nosili pod zemlju kao rano upozorenje.","also":["canary release","canary releases","canary","probno izdanje"]},{"id":"bluegreen","g":"change","word":"Plavo-zeleno postavljanje","text":"Drže se dvije kopije sustava uživo, a ljudi se odjednom prebace na novu, pa se možeš odmah vratiti ako nešto pođe po zlu.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Postavljanje bez prekida","text":"Puštanje nove verzije uživo, a da usluga ni u jednom trenutku ne stane za svoje korisnike.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Upravljanje promjenama","text":"Pomaganje da promjene uspiju: vaganje rizika, dobivanje pravog odobrenja i izbor dobrog trenutka. Zove se i change management.","also":["change enablement","change management","upravljanje promjenom"]},{"id":"cab","g":"change","word":"Savjetodavni odbor za promjene (CAB)","text":"Skupina koja pregledava važne promjene i dogovara smiju li i kada ići dalje.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Standardna promjena","text":"Promjena niskog rizika koja se svaki put radi na isti iskušan način, pa je unaprijed odobrena.","also":["standardne promjene","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Normalna promjena","text":"Promjena koju treba provjeriti i odobriti prije nego što krene.","also":["normalne promjene","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Hitna promjena","text":"Promjena koja se mora dogoditi odmah da bi se popravila ili spriječila ozbiljna nevolja, s odgovarajuće bržim odobrenjem.","also":["hitne promjene","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automatizacija","text":"Računalo samo obavlja ponavljajući posao, pa je brže i uvijek napravljeno na isti način.","also":["automation","automated","automatizirano"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktura","text":"Strojevi, mreže i usluge na kojima softver radi.","also":["infrastructure","infra"]},{"id":"iac","g":"change","word":"Infrastruktura kao kod (IaC)","text":"Opisivanje poslužitelja i postavki u datotekama koje se čuvaju uz kod, pa se mogu svaki put iznova izgraditi točno isto.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Oblak (Cloud)","text":"Unajmljivanje računala, pohrane i usluga od velikog pružatelja preko interneta, umjesto da strojeve posjeduješ.","also":["cloud","the cloud","cloud computing","računalstvo u oblaku"]},{"id":"provider","g":"change","word":"Pružatelj usluga u oblaku","text":"Tvrtka koja iznajmljuje računalnu snagu preko interneta, poput Amazon Web Services (AWS), Microsoft Azurea ili Google Clouda.","also":["pružatelji usluga u oblaku","pružatelj oblaka","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Mjesto gdje tvoja aplikacija ili web-stranica živi i radi da joj ljudi mogu pristupiti, obično unajmljeno od tvrtke.","also":["web hosting","hostinga","hosting"]},{"id":"domain","g":"change","word":"Naziv domene","text":"Web-adresa koju ljudi upisuju, poput example.com. Iznajmljuje se na godinu, pa se mora obnavljati.","also":["nazivi domena","domena","domene","domenu","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Kratica za domain name system: adresar interneta koji naziv poput example.com pretvara u adresu pravog računala.","also":["domain name system","sustav naziva domena"]},{"id":"container","g":"change","word":"Kontejner","text":"Zapečaćen paket s aplikacijom i svime što joj treba, pa radi jednako na svakom računalu. Docker je najpoznatiji alat.","also":["kontejneri","kontejnera","kontejneru","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtualni stroj (VM)","text":"Prividno računalo koje radi unutar pravog, pa jedan veliki stroj može glumiti mnogo njih.","also":["VM","VMs","virtual machine","virtual machines","virtualni strojevi"]},{"id":"serverless","g":"change","word":"Bez poslužitelja (Serverless)","text":"Pokretanje koda bez brige o ikakvim poslužiteljima: pružatelj ga pokreće kad zatreba, a ti plaćaš ono što koristiš."},{"id":"lb","g":"change","word":"Uravnoteživač opterećenja","text":"Nešto što raspoređuje posjetitelje na nekoliko poslužitelja, da nijedan ne bude preopterećen.","also":["load balancer","load balancers","balanser"]},{"id":"cache","g":"change","word":"Predmemorija (Cache)","text":"Spremište nedavnih rezultata nadohvat ruke, da se isto ne mora ponovno dohvaćati ili računati. Njegovo pražnjenje može popraviti stranice koje izgledaju zastarjelo.","also":["predmemorija","predmemorije","keš","cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Mreža za isporuku sadržaja (CDN)","text":"Svjetska mreža poslužitelja koji drže kopije tvojih stranica i slika blizu posjetitelja, da se brzo učitavaju.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migracija","text":"Premještanje podataka ili sustava sa starog postava na novi ili pažljiva promjena rasporeda baze podataka.","also":["migracije","migraciju","migraciji","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Servis","text":"Nešto što si napravio, a ljudi o tome ovise, poput web-stranice ili aplikacije, o čemu se brine da nastavi raditi. Označi „Ovaj projekt je servis” i reci što nudi, tko ga koristi i tko je dežuran.","also":["servisi","usluga","service"]},{"id":"uptimepct","g":"run","word":"Dostupnost (Uptime)","text":"Koliko vremena usluga radi, obično u postocima. 99,9 % i dalje dopušta oko 43 minute prekida mjesečno.","also":["uptime","uptime percentage","postotak dostupnosti"]},{"id":"uptime","g":"run","word":"Provjera dostupnosti","text":"Automatska provjera, svakih nekoliko minuta, da tvoj servis još odgovara. Ako nekoliko puta zaredom ne uspije, AI-gile sam otvara karticu incidenta.","also":["uptime checks","provjere dostupnosti"]},{"id":"statuspage","g":"run","word":"Statusna stranica","text":"Javna stranica koja pokazuje radi li servis (zeleno, narančasto ili crveno) uz najnoviju obavijest, kako bi ljudi koji ga koriste mogli sami provjeriti umjesto da pitaju.","also":["statusne stranice","status page"]},{"id":"desk","g":"run","word":"Servisni pult","text":"Mjesto na koje stižu pitanja i prijave ljudi koji koriste tvoj servis. AI-gile svaku razvrsta u zahtjev, incident ili ideju i javi kad izgleda kao nešto što je već prijavljeno.","also":["servisni pultovi","služba za pomoć","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Servisni zahtjev","text":"Netko traži nešto uobičajeno, poput novog računa ili malo pomoći, umjesto da prijavi da je nešto pokvareno. Čeka svoj red; incident ide prvi.","also":["servisni zahtjevi"]},{"id":"incident","g":"run","word":"Incident","text":"Nešto što je pokvareno ili ne radi kako treba za ljude koji ga trenutačno koriste, poput web-stranice koja ne radi ili je jako spora. 🔥 Kartica incidenta preskače red: najvažnije je da opet proradi.","also":["incidenti","incidenta","incident"]},{"id":"major","g":"run","word":"Veliki incident","text":"Ozbiljan incident: pogođeno je mnogo ljudi ili su novac ili podaci u opasnosti. Jedan gumb stavlja sve timove na njega (swarm), budi onoga tko je dežuran i traži novu obavijest o statusu svakih 30 minuta.","also":["veliki incidenti","major incident"]},{"id":"oncall","g":"run","word":"Dežurstvo","text":"Biti onaj koji odgovara kad se nešto pokvari, čak i noću. Svaki servis ima dežurnog člana tima kojeg se prvog budi za njegove incidente.","also":["dežuran","dežurni","on call","on-call"]},{"id":"replyby","g":"run","word":"Rok za odgovor","text":"Koliko kartica smije čekati prvi odgovor, npr. sat vremena za incident. Nakon toga dobiva crveni sat, da se ništa tiho ne zaboravi. Zove se i ciljano vrijeme odgovora.","also":["rokovi za odgovor","ciljano vrijeme odgovora","response target"]},{"id":"postmortem","g":"run","word":"Analiza incidenta","text":"Kratak osvrt nakon incidenta: što se dogodilo, što je pomoglo i što promijeniti, bez okrivljavanja ikoga. Incident se ne može zatvoriti bez nje.","also":["post-mortem","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"Skriveni uzrok jednog ili više incidenata. Kartica 🧩 problem okuplja incidente koji se stalno vraćaju, kako bi se uzrok pronašao i zauvijek popravio.","also":["problemi","problema","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Temeljni uzrok","text":"Pravi razlog zašto se nešto pokvarilo, ne samo ono što si vidio da ne radi. Popravi temeljni uzrok i incident se prestaje vraćati.","also":["korijenski uzrok","root cause"]},{"id":"workaround","g":"run","word":"Zaobilazno rješenje","text":"Način da stvari rade dok pravi popravak ne bude spreman, npr. ponovno pokretanje nečega kad zapne. Zapisuje se na karticu problema da ga nitko ne mora ponovno smišljati.","also":["zaobilazna rješenja","workaround"]},{"id":"knownerror","g":"run","word":"Poznata greška","text":"Problem čiji je uzrok poznat, ali još nije popravljen, obično s zapisanim zaobilaznim rješenjem. „🧩 Poznate greške“ ih navodi, da svi koriste zaobilazno rješenje umjesto da ponovno kopaju.","also":["poznate greške","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Upute korak po korak za popravak poznate vrste problema, da se svaki put napravi isto i brzo. Nakon velikog incidenta tim ti može predložiti jedan da mu daš OK.","also":["runbooks","runbooka"]},{"id":"ci","g":"run","word":"Konfiguracijska stavka","text":"Jedna stvar o kojoj tvoj servis ovisi, poput poslužitelja, domene, certifikata, ključa ili dobavljača. 🗂️ Konfiguracijske stavke navode ih po servisu, da vidiš na što incident utječe i što treba obnoviti ili sigurnosno kopirati.","also":["konfiguracijske stavke","konfiguracijskih stavki"]},{"id":"expiry","g":"run","word":"Datum isteka","text":"Datum nakon kojeg nešto prestaje raditi ako se ne obnovi, poput sigurnosnog certifikata web-stranice ili njezine web-adrese. AI-gile prati te datume i izrađuje po jednu karticu za obnovu 30 dana ranije, da ništa ne stane iznenada.","also":["datumi isteka","istek","praćenje isteka"]},{"id":"backup","g":"run","word":"Sigurnosna kopija","text":"Spremljena ranija kopija tvojih podataka, na koju se možeš osloniti ako se nešto izgubi ili ošteti. AI-gile svaki dan radi sigurnosnu kopiju tvojih ploča.","also":["sigurnosne kopije","backup","backups"]},{"id":"restore","g":"run","word":"Vraćanje","text":"Vraćanje podataka iz sigurnosne kopije. Sigurnosna kopija stvarno vrijedi tek kad znaš da se može vratiti, pa se isplati to povremeno isprobati.","also":["vratiti","vraćeno","restore"]},{"id":"svcreview","g":"run","word":"Pregled servisa","text":"Pogled unatrag na jedan mjesec servisa: otvoreni i popravljeni incidenti, koliko su brzo ljudi dobili odgovor, dostupnost i potrošeni tokeni. Mjesečni pregled to prikazuje za svaki servis.","also":["pregledi servisa","mjesečni pregled","mjesečni pregledi"]},{"id":"accessreview","g":"run","word":"Pregled pristupa","text":"Provjera svakih 90 dana tko još može ući: poveznice za dijeljenje, uloge prijatelja te spremljene lozinke i ključevi. Svaki zadržiš ili ukloniš, da stari pristup ne ostane visjeti.","also":["pregledi pristupa"]},{"id":"improvements","g":"run","word":"Popis poboljšanja","text":"Sve u čemu je tim odlučio postati bolji, na jednom mjestu: prijedlozi s retrospektive, akcije pregleda i popravci problema, svaki sa svojim statusom. Nađi ga pod 📈 Poboljšanja.","also":["popisi poboljšanja","poboljšanja"]},{"id":"tokencap","g":"run","word":"Limit tokena","text":"Mjesečno ograničenje tokena koje agenti jednog servisa smiju potrošiti. Na 80% dobivaš upozorenje; na 100% njihov rad u pozadini čeka sljedeći mjesec ili dok ne podigneš limit.","also":["limiti tokena","token cap"]},{"id":"svcmgmt","g":"run","word":"Upravljanje uslugama","text":"Sve što je potrebno da usluga ostane korisna i da radi za ljude koji se na nju oslanjaju, iz dana u dan.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Široko korišten vodič za dobro upravljanje uslugama, koji pokriva stvari poput incidenata, problema i promjena. Ime je nekoć značilo IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Upravljanje IT uslugama (ITSM)","text":"Vođenje tehnologije kao usluge za ljude, s jasnim načinima rješavanja zahtjeva, incidenata, promjena i poboljšanja.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Upravljana usluga","text":"Usluga koju netko drugi umjesto tebe pokreće i održava, prema dogovoru koliko dobro mora raditi.","also":["upravljane usluge","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Vlasnik usluge","text":"Osoba koja odgovara za uslugu u cjelini: koliko dobro radi, koliko košta i kako se poboljšava.","also":["vlasnici usluga","vlasnika usluge","service owner","service owners"]},{"id":"sla","g":"run","word":"Ugovor o razini usluge (SLA)","text":"Pisano obećanje korisnicima o tome koliko će dobro usluga raditi, poput „radi 99,9 % vremena“ ili „odgovor u roku od sat vremena“, često uz povrat novca ako se prekrši.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Cilj razine usluge (SLO)","text":"Vlastiti cilj tima o tome koliko dobro usluga treba raditi u nekom razdoblju, obično malo stroži od SLA-a radi sigurnosti.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Pokazatelj razine usluge (SLI)","text":"Stvarno mjerenje koje uspoređuješ s ciljem, poput udjela posjeta koji su se dobro učitali.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Raspoloživost (Availability)","text":"Mogu li ljudi koristiti uslugu kad im treba, često mjereno postotkom dostupnosti (uptime).","also":["availability","high availability","visoka raspoloživost"]},{"id":"downtime","g":"run","word":"Zastoj (Downtime)","text":"Vrijeme kad usluga ne radi ili je isključena, planirano ili ne.","also":["downtime","down time","prekid rada"]},{"id":"errorbudget","g":"run","word":"Proračun za greške","text":"Mala količina neuspjeha koju tvoj cilj pouzdanosti dopušta. Dok ga ima, možeš riskirati s promjenama; kad se potroši, usporavaš.","also":["error budget","error budgets","budžet za greške"]},{"id":"outage","g":"run","word":"Ispad (Outage)","text":"Vrijeme kad usluga ne radi ili je jako pokvarena za svoje korisnike.","also":["ispadi","outage","outages"]},{"id":"degraded","g":"run","word":"Smanjena kvaliteta (Degraded)","text":"Radi, ali loše: sporo ili s nekim dijelovima koji ne rade.","also":["degraded","degraded service","degradirana usluga"]},{"id":"monitoring","g":"run","word":"Praćenje (Monitoring)","text":"Automatsko promatranje usluge cijelo vrijeme, da se problemi uoče, po mogućnosti prije korisnika.","also":["monitoring"]},{"id":"observability","g":"run","word":"Vidljivost sustava (Observability)","text":"Koliko dobro izvana možeš razabrati što se događa unutar sustava, pomoću njegovih zapisnika, brojeva i tragova.","also":["opservabilnost","observability","o11y"]},{"id":"log","g":"run","word":"Zapisnik (Log)","text":"Dnevnik koji program neprestano vodi o tome što radi, a koristi se za otkrivanje što je pošlo po zlu.","also":["zapisnici","zapisnika","logovi","loga","log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trag (Trace)","text":"Zapis kako jedan zahtjev putuje kroz različite dijelove sustava, korak po korak, koji pokazuje gdje je usporio.","also":["trace","traces","tracing"]},{"id":"latency","g":"run","word":"Latencija","text":"Koliko nešto traje dok odgovori, poput čekanja između klika i pojave stranice.","also":["latency"]},{"id":"alert","g":"run","word":"Upozorenje (Alert)","text":"Automatska poruka da nešto traži pažnju, na primjer web-stranica ne odgovara.","also":["upozorenja","upozorenje","alarm","alarmi","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Zamor od upozorenja","text":"Kad je upozorenja toliko da ih ljudi počnu ignorirati, uključujući ona važna.","also":["alert fatigue","alarm fatigue","zamor od alarma"]},{"id":"dashboard","g":"run","word":"Nadzorna ploča (Dashboard)","text":"Zaslon koji jednim pogledom pokazuje najvažnije brojeve i stanja.","also":["nadzorne ploče","nadzornu ploču","dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Dojava (Paging)","text":"Hitno pozivanje ili buđenje dežurne osobe zbog problema.","also":["paging","paged","prozivanje"]},{"id":"escalation","g":"run","word":"Eskalacija","text":"Uključivanje nekoga s više znanja ili ovlasti kad se problem ne može riješiti na trenutnoj razini ili se ne rješava dovoljno brzo.","also":["eskalirati","escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Trijaža","text":"Brzo razvrstavanje pristiglih problema prema hitnosti i važnosti, da se najgore riješi prvo.","also":["triage","triaged","trijažiranje"]},{"id":"impact","g":"run","word":"Utjecaj (Impact)","text":"Koliko nešto pogađa ljude: koliko ih je i koliko jako.","noTip":1},{"id":"urgency","g":"run","word":"Hitnost (Urgency)","text":"Koliko brzo se nečim treba pozabaviti. Utjecaj i hitnost zajedno određuju prioritet.","noTip":1},{"id":"plevels","g":"run","word":"Razine prioriteta (P1, P2…)","text":"Oznake koliko je problem hitan. P1 je najozbiljniji i traži akciju odmah.","also":["P1","P2","P3","P4","razine prioriteta"]},{"id":"queue","g":"run","word":"Red tiketa","text":"Popis zahtjeva i incidenata koji čekaju da ih netko preuzme.","also":["redovi tiketa","ticket queue","ticket queues","red zahtjeva"]},{"id":"tiers","g":"run","word":"Prva i druga linija","text":"Razine podrške: prva linija prima poziv i rješava jednostavne stvari; druga ima dublja znanja za teže. Zovu se i tier 1 i tier 2.","also":["prva linija","druga linija","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Voditelj incidenta","text":"Jedna osoba koja vodi odgovor na incident, da svi znaju tko odlučuje, a tko što radi.","also":["voditelji incidenta","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Vrijeme odziva","text":"Koliko prođe dok netko prvi put ne preuzme zahtjev ili incident.","also":["vremena odziva","response time","response times"]},{"id":"resolution","g":"run","word":"Vrijeme rješavanja","text":"Koliko traje da se zahtjev ili incident posve riješi, od prijave do popravka.","also":["vremena rješavanja","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Prosječno vrijeme oporavka (MTTR)","text":"U prosjeku koliko treba da usluga opet proradi nakon kvara. MTTR može značiti malo različite stvari, pa reci što točno mjeriš.","also":["MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Prosječno vrijeme između kvarova (MTBF)","text":"U prosjeku koliko dugo usluga radi prije nego što se nešto pokvari.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Baza konfiguracija (CMDB)","text":"Popis svih tvojih konfiguracijskih stavki i kako su povezane, da vidiš što o čemu ovisi.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Imovina (Asset)","text":"Sve vrijedno što posjeduješ ili plaćaš da usluga radi, poput prijenosnog računala, softverske licence ili domene.","also":["asset","assets","resursi"],"noTip":1},{"id":"capplan","g":"run","word":"Planiranje kapaciteta","text":"Briga da će biti dovoljno računalne snage, pohrane i ljudi za ono što dolazi.","also":["capacity planning","capacity plan","plan kapaciteta"]},{"id":"scaling","g":"run","word":"Skaliranje","text":"Prilagodba većem broju korisnika: stroju se da više snage (skaliranje prema gore) ili se dodaju novi strojevi (skaliranje u širinu).","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Kontinuitet poslovanja","text":"Planovi kako nastaviti važne stvari kad nešto veliko pođe po zlu, poput gubitka ureda, ključnog dobavljača ili računala.","also":["business continuity","business continuity plan","plan kontinuiteta"]},{"id":"dr","g":"run","word":"Oporavak od katastrofe (DR)","text":"Plan i alati za vraćanje usluge nakon nečeg ozbiljnog, poput gubitka cijelog podatkovnog centra.","also":["disaster recovery","DR"]},{"id":"rto","g":"run","word":"Ciljno vrijeme oporavka (RTO)","text":"Najdulje vrijeme koje usluga smije biti nedostupna nakon katastrofe prije nego što opet mora raditi.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Ciljna točka oporavka (RPO)","text":"Koliko si nedavnih podataka možeš priuštiti izgubiti, mjereno vremenom. RPO od jednog sata znači sigurnosne kopije barem svakog sata.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redundancija","text":"Spremne zamjene, poput drugog poslužitelja, da jedan kvar ne zaustavi uslugu.","also":["redundantno","redundancy"]},{"id":"failover","g":"run","word":"Automatski prelazak (Failover)","text":"Automatski prelazak na rezervni sustav kad uobičajeni zakaže.","also":["prebacivanje na rezervu","failover","fail over"]},{"id":"spof","g":"run","word":"Jedinstvena točka otkaza","text":"Jedan dio koji sa sobom sruši sve kad se pokvari, jer nema zamjene.","also":["jedinstvene točke otkaza","single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Prozor za održavanje","text":"Planirano vrijeme kad usluga smije biti pauzirana ili spora zbog održavanja, unaprijed najavljeno korisnicima.","also":["prozori za održavanje","maintenance window","maintenance windows","planned maintenance","planirano održavanje"]},{"id":"handover","g":"run","word":"Primopredaja (Handover)","text":"Predavanje posla, znanja i odgovornosti drugoj osobi ili timu, da se ništa ne izgubi.","also":["primopredaja","primopredaje","handover","handovers"]},{"id":"kb","g":"run","word":"Baza znanja","text":"Zbirka članaka pomoći i odgovora, za korisnike i za tim.","also":["baze znanja","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Zadovoljstvo korisnika (CSAT)","text":"Ocjena korisnika koliko su bili zadovoljni, koja se često traži nakon zatvaranja zahtjeva.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Dobavljač","text":"Vanjska tvrtka na koju se oslanjaš, poput pružatelja hostinga. Zove se i vendor ili treća strana.","also":["dobavljači","dobavljača","dobavljaču","treća strana","supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Gašenje usluge","text":"Trajno i sigurno isključivanje usluge: obavještavanje korisnika, rješavanje njezinih podataka i pristupa te zaustavljanje troškova.","also":["povlačenje usluge","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Kraj životnog vijeka (EOL)","text":"Kad proizvođač prestane davati ažuriranja ili podršku za proizvod, pa ga treba zamijeniti.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Kibernetička sigurnost","text":"Zaštita sustava i podataka od provale, krađe ili oštećenja.","also":["cybersecurity","cyber security","kibersigurnost"]},{"id":"authn","g":"sec","word":"Autentifikacija (Authentication)","text":"Provjera tko je netko, obično lozinkom ili kodom. Često se skraćuje na authn.","also":["authentication","authn","provjera identiteta"]},{"id":"authz","g":"sec","word":"Autorizacija (Authorisation)","text":"Provjera što je nekome dopušteno kad već znaš tko je. Često se skraćuje na authz.","also":["authz","authorization","autorizacija"]},{"id":"mfa","g":"sec","word":"Višefaktorska autentifikacija (MFA)","text":"Prijava s dva ili više dokaza, poput lozinke i koda na telefonu. Zove se i dvofaktorska (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","dvofaktorska autentifikacija"]},{"id":"sso","g":"sec","word":"Jedinstvena prijava (SSO)","text":"Prijaviš se jednom i uđeš u mnoge sustave, poput korištenja poslovnog računa posvuda.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Upravitelj lozinki","text":"Aplikacija koja izrađuje jake lozinke i pamti ih umjesto tebe.","also":["upravitelji lozinki","password manager","password managers"]},{"id":"secret","g":"sec","word":"Tajna (Secret)","text":"Lozinka, ključ ili drugi privatni kod kojim program ulazi u nešto. Nikad se ne smije dijeliti niti upisivati u kod.","also":["tajne","tajnu","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API ključ","text":"Tajni kod koji programu dopušta korištenje API-ja druge usluge i pokazuje tko ga koristi (i plaća).","also":["API ključevi","API ključa","API ključem","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Pristupni token","text":"Privremena propusnica koja dokazuje da je programu dopušteno ući, pa ne treba tvoju lozinku svaki put. Nije isto što i AI token.","also":["pristupni tokeni","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Šifriranje","text":"Pretvaranje informacija u nečitljiv oblik, tako da ih može pročitati samo onaj tko ima pravi ključ.","also":["šifriranje","šifrirano","enkripcija","šifrirati","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Siguran način na koji web-stranice putuju, prikazan lokotom u pregledniku, da ih nitko usput ne može čitati ili mijenjati."},{"id":"cert","g":"sec","word":"SSL/TLS certifikat","text":"Digitalna osobna iskaznica kojom web-stranica dokazuje tko je i može koristiti HTTPS. Istječe, pa se mora obnavljati.","also":["certifikat","certifikati","certifikata","TLS certifikat","SSL certifikat","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Dozvole","text":"Pravila tko što smije vidjeti ili mijenjati.","also":["dozvole","dozvola","ovlasti","prava pristupa","permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Najmanje ovlasti (Least privilege)","text":"Svakoj osobi ili programu daje se samo pristup koji je doista potreban, i samo dok je potreban.","also":["načelo najmanjih ovlasti","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Kontrola pristupa po ulogama (RBAC)","text":"Davanje pristupa prema ulozi, poput gledatelja ili urednika, umjesto osobu po osobu.","also":["RBAC","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"Ranjivost","text":"Slabost koju bi netko mogao iskoristiti za provalu ili nanošenje štete.","also":["ranjivosti","ranjivost","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day (nulti dan)","text":"Slabost za koju napadači znaju prije nego što su je izrađivači stigli popraviti.","also":["zero-day","zero-days","zero day","nulti dan"]},{"id":"malware","g":"sec","word":"Zlonamjerni softver (Malware)","text":"Štetan softver, poput virusa, napravljen da oštećuje, špijunira ili krade.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Ransomware (softver za iznudu)","text":"Zlonamjerni softver koji zaključa tvoje datoteke i traži novac da ih otključa. Dobre sigurnosne kopije najbolja su obrana.","also":["ransomware","ransomware attack","ucjenjivački virus"]},{"id":"phishing","g":"sec","word":"Phishing (krađa podataka lažnim porukama)","text":"Lažne poruke koje te pokušavaju navesti da odaš lozinke ili novac ili otvoriš nešto štetno.","also":["phishing","phishing email","phishing emails","phishing e-pošta","lažne poruke"]},{"id":"socialeng","g":"sec","word":"Socijalni inženjering","text":"Varanje ljudi, a ne računala, da daju pristup, poput lažnog poziva „IT podrške“."},{"id":"firewall","g":"sec","word":"Vatrozid (Firewall)","text":"Čuvar koji odlučuje koji mrežni promet smije ući ili izaći.","also":["vatrozid","vatrozida","vatrozidovi","firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Kratica za virtual private network (virtualna privatna mreža): privatna, šifrirana veza preko interneta, često korištena za siguran pristup poslovnim sustavima.","also":["virtual private network","virtualna privatna mreža"]},{"id":"ddos","g":"sec","word":"Uskraćivanje usluge (DoS, DDoS)","text":"Zatrpavanje usluge tolikom količinom lažnog prometa da je stvarni ljudi ne mogu koristiti. DDoS znači da promet dolazi s mnogo računala odjednom.","also":["DoS","DDoS","denial of service","DDoS attack","DDoS napad"]},{"id":"pentest","g":"sec","word":"Penetracijski test (pen test)","text":"Angažiranje prijateljskih stručnjaka koji pokušavaju provaliti, da se slabosti nađu prije nego ih nađu pravi napadači.","also":["pen test","pen testing","penetration test","penetration testing","pentest","penetracijsko testiranje"]},{"id":"audit","g":"sec","word":"Sigurnosna revizija","text":"Pažljiva provjera koliko je nešto dobro zaštićeno, prema popisu dobre prakse.","also":["sigurnosne revizije","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Modeliranje prijetnji","text":"Razmišljanje o tome tko bi mogao nešto napasti, kako, i što možeš učiniti da ga zaustaviš.","also":["threat model","threat modelling","threat modeling","model prijetnji"]},{"id":"breach","g":"sec","word":"Curenje podataka","text":"Kad privatne informacije dođu do ljudi koji ih ne bi smjeli imati, ili se izgube ili izmijene bez dopuštenja.","also":["curenje podataka","povreda podataka","povreda osobnih podataka","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Osobni podaci","text":"Svaka informacija o osobi koja se može prepoznati, poput imena, adrese e-pošte ili lokacije. Takvi se podaci zovu i PII.","also":["PII","personally identifiable information","osobne informacije"]},{"id":"gdpr","g":"sec","word":"GDPR (Opća uredba o zaštiti podataka)","text":"Europski zakon o osobnim podacima (UK ima vlastitu verziju): prikupljaj samo ono što trebaš, čuvaj to sigurno i dopusti ljudima da vide ili izbrišu svoje.","also":["GDPR","Opća uredba o zaštiti podataka","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Zaštita podataka","text":"Pravilno postupanje s osobnim podacima, u skladu sa zakonom.","also":["data protection","data protection law","zakon o zaštiti podataka"]},{"id":"privacypolicy","g":"sec","word":"Pravila privatnosti","text":"Javna stranica koja kaže koje osobne podatke prikupljaš, zašto i što s njima radiš.","also":["politika privatnosti","privacy policy","privacy statement","privacy notice","izjava o privatnosti"]},{"id":"consent","g":"sec","word":"Privola","text":"Jasno, slobodno „da“ osobe da se njezini podaci koriste na određeni način. Može ga povući bilo kada.","also":["pristanak","consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Kolačić (Cookie)","text":"Mala datoteka koju web-stranica sprema u tvom pregledniku da bi nešto zapamtila, na primjer tvoju prijavu. Za neke je prvo potrebna tvoja privola.","also":["kolačići","kolačića","kolačiće","cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Smanjenje količine podataka","text":"Prikupljanje i čuvanje samo onih osobnih podataka koji su doista potrebni za posao.","also":["minimizacija podataka","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Rok čuvanja podataka","text":"Koliko se dugo podaci čuvaju prije brisanja. Čuvati ih ne dulje nego što treba sigurnije je i često zakonski obvezno.","also":["čuvanje podataka","data retention","retention period"]},{"id":"anon","g":"sec","word":"Anonimizacija","text":"Promjena podataka tako da se na temelju njih više nitko ne može razumno prepoznati.","also":["anonimizirani podaci","anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonimizacija","text":"Zamjena imena i drugih pojedinosti šiframa, uz ključ čuvan odvojeno za povezivanje natrag. To su i dalje osobni podaci.","also":["pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Ugovor o obradi podataka (DPA)","text":"Ugovor koji kaže kako dobavljač smije postupati s osobnim podacima u tvoje ime.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Procjena učinka na zaštitu podataka (DPIA)","text":"Pažljiv pogled, prije početka, kako bi plan korištenja osobnih podataka mogao utjecati na ljude i kako smanjiti rizike.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Revizijski zapisnik","text":"Zapis tko je što učinio i kada, da se radnje mogu naknadno provjeriti.","also":["revizijski zapisnici","audit log","audit logs","audit trail","revizijski trag"]},{"id":"compliance","g":"sec","word":"Usklađenost (Compliance)","text":"Poštivanje zakona, pravila i standarda koji se na tebe odnose i sposobnost da to pokažeš.","also":["sukladnost","compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Poznat međunarodni standard za upravljanje informacijskom sigurnošću. Tvrtke se mogu certificirati prema njemu.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Američko izvješće, koje provjeravaju vanjski revizori, a pokazuje da tvrtka pravilno brine o podacima korisnika.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI koji sam radi na zadatku: čita kod, mijenja ga, pokreće provjere i javlja natrag. Njegov se rad ipak provjerava.","also":["agenti","agenta","agentu","agents"]},{"id":"token","g":"ai","word":"Token","text":"Mali komadići teksta koje AI čita i piše, svaki otprilike tri četvrtine riječi. Korištenje AI-ja broji se u tokenima, pa manje tokena ostavlja više tvog plana.","also":["tokeni","tokena","tokenu","tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Mala naredba koja se sama pokreće u određenom trenutku, na primjer kad počne AI sesija, da tim čuje tvoje komentare.","also":["hookovi","hooka","hookove","hook","hooks"]},{"id":"ai","g":"ai","word":"Umjetna inteligencija (AI)","text":"Računalni sustavi koji rade stvari za koje obično mislimo da trebaju čovjeka, poput pisanja, odgovaranja na pitanja ili prepoznavanja slika.","also":["AI","AI-ja","AI-ju","umjetna inteligencija","umjetne inteligencije","umjetnu inteligenciju","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Strojno učenje (ML)","text":"Način da računala nauče obrasce iz mnogo primjera, umjesto da im se daju točna pravila.","also":["machine learning","ML"]},{"id":"model","g":"ai","word":"Model","text":"Istrenirani „mozak“ AI sustava, nastao učenjem iz golemog broja primjera. Modeli se razlikuju po sposobnostima, brzini i cijeni.","also":["modeli","modela","modelu","AI model","model","models"],"noTip":1},{"id":"llm","g":"ai","word":"Veliki jezični model (LLM)","text":"AI model treniran na golemim količinama teksta, pa može čitati i pisati jezik.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"Generativni AI","text":"AI koji stvara nove stvari, poput teksta, slika ili koda, a ne samo razvrstava ili uočava.","also":["GenAI","generative AI","generativna umjetna inteligencija"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Program s kojim razgovaraš običnim jezikom, tipkanjem ili govorom.","also":["chatbotovi","chatbota","chatbotu","chatbot","chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Ono što daješ AI-ju: svoje pitanje ili upute, plus sve što mu predaš. Jasniji promptovi obično daju bolje odgovore.","also":["promptovi","prompta","promptu","prompt","prompts"]},{"id":"prompteng","g":"ai","word":"Pisanje promptova (Prompt engineering)","text":"Vještina pisanja promptova koji daju pouzdane, korisne rezultate.","also":["prompt engineering","prompt inženjering"]},{"id":"sysprompt","g":"ai","word":"Sistemski prompt","text":"Pozadinske upute koje AI dobije prije početka razgovora, a određuju njegovu ulogu i pravila. Imaju veću težinu od onoga što ti upišeš.","also":["sistemski promptovi","system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Kontekst","text":"Sve što AI vidi dok radi: upute, tvoje poruke, pročitane datoteke i raniji odgovori.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontekstni prozor","text":"Koliko AI može držati na umu odjednom, mjereno u tokenima. Preko toga se stariji dijelovi izbacuju ili sažimaju.","also":["kontekstni prozori","context window","context windows"]},{"id":"session","g":"ai","word":"Sesija","text":"Jedan radni razgovor s AI-jem, od početka do kraja. Nova sesija počinje sa svježom memorijom.","also":["sesije","sesiju","sesiji","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memorija","text":"Bilješke koje AI čuva između sesija, pa pamti tvoje sklonosti i prošle odluke.","noTip":1},{"id":"hallucination","g":"ai","word":"Halucinacija","text":"Kad AI kaže nešto što zvuči samouvjereno, ali je izmišljeno ili pogrešno. Provjeri važne činjenice.","also":["halucinacije","halucinira","halucinirati","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Treniranje","text":"Učenje modela pokazivanjem golemog broja primjera, prije nego što ga itko koristi.","also":["učenje modela","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Podaci za treniranje","text":"Primjeri iz kojih je model učio. Njegovo znanje staje na datumu kad su ti podaci prikupljeni.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"Granica znanja","text":"Datum do kojeg seže ugrađeno znanje AI-ja. Za kasnije stvari neće znati, osim ako ih potraži.","also":["knowledge cutoff","training cutoff","datum odsijecanja"]},{"id":"finetune","g":"ai","word":"Fino ugađanje (Fine-tuning)","text":"Dodatno treniranje postojećeg modela na tvojim primjerima, da postane bolji u jednom određenom poslu.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning","dotreniravanje"]},{"id":"inference","g":"ai","word":"Zaključivanje (Inference)","text":"Stvarno korištenje AI modela za odgovaranje na nešto, za razliku od njegova treniranja.","also":["inference","model inference","inferencija"]},{"id":"tooluse","g":"ai","word":"Korištenje alata","text":"AI koji može raditi stvari, a ne samo razgovarati: pokretati naredbe, čitati datoteke ili pretraživati web, pomoću alata koje mu aplikacija daje.","also":["tool use","tool calling","tool call","tool calls","pozivanje alata"]},{"id":"subagent","g":"ai","word":"Podagent (Subagent)","text":"Pomoćni AI kojem glavni AI povjeri manji posao i od kojeg dobije rezultat.","also":["podagenti","podagenta","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Više agenata (Multi-agent)","text":"Nekoliko AI-jeva radi zajedno na jednom poslu, svaki sa svojim dijelom, poput malog tima.","also":["multi-agent","multi-agent system","višeagentni sustav"]},{"id":"autonomy","g":"ai","word":"Samostalnost (Autonomy)","text":"Koliko AI smije sam napraviti prije nego što mora pitati osobu.","also":["autonomy","autonomous","autonomija"]},{"id":"hitl","g":"ai","word":"Čovjek u petlji","text":"Osoba ostaje uključena da u ključnim trenucima provjerava ili odobrava što AI radi. U AI-gileu to si ti.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Zaštitne ograde (Guardrails)","text":"Granice i provjere koje drže radnje AI-ja sigurnima, poput potrebe odobrenja prije nego što išta krene uživo. Smanjuju rizik od grešaka, ali ga ne isključuju.","also":["guardrails","guardrail"]},{"id":"rag","g":"ai","word":"Generiranje uz dohvat (RAG)","text":"AI traži podatke u tvojim dokumentima prije nego što odgovori, pa se njegovi odgovori temelje na tvojim činjenicama.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (vektorski prikaz)","text":"Pretvaranje teksta u popis brojeva koji hvata njegovo značenje, da računalo može pronaći stvari sličnog značenja.","also":["embeddinzi","embeddinga","vektorski prikaz","embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Vektorska baza podataka","text":"Baza podataka napravljena za pretraživanje tih popisa brojeva (embeddinga), da nađe materijal sličnog značenja.","also":["vektorske baze podataka","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Zajednički način da se alati i izvori podataka priključe AI aplikacijama, pa ih AI može koristiti.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Postavka koliko su odgovori AI-ja odvažni. Niska daje postojanije, predvidljivije odgovore, visoka raznolikije. Nijedna ga ne čini uvijek točnim.","also":["temperature","model temperature","temperatura modela"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodalan","text":"Može raditi s više vrsta informacija, poput teksta, slika i zvuka.","also":["multimodal","multi-modal","multimodalni"]},{"id":"evals","g":"ai","word":"Evaluacija (eval)","text":"Planirani test koliko dobro AI radi na odabranim primjerima, da možeš uspoređivati modele ili promptove.","also":["eval","evals","evaluation","evaluacije"]},{"id":"bias","g":"ai","word":"Pristranost (Bias)","text":"Kad AI (ili osoba) nepravedno naginje na jednu stranu, često zbog onoga iz čega je učio.","also":["bias","biased","pristrano"],"noTip":1},{"id":"responsible","g":"ai","word":"Odgovoran AI","text":"Pošteno, sigurno i iskreno korištenje AI-ja, pri čemu ljudi i dalje odgovaraju za rezultate.","also":["responsible AI","ethical AI","etički AI"]},{"id":"injection","g":"ai","word":"Ubacivanje prompta (Prompt injection)","text":"Trik u kojem skrivene upute u web-stranici ili datoteci pokušavaju natjerati AI da učini nešto što njegov korisnik nije tražio.","also":["prompt injection","prompt injections","injekcija prompta"]},{"id":"ratelimit","g":"ai","word":"Ograničenje broja zahtjeva","text":"Gornja granica broja zahtjeva koje smiješ poslati usluzi u zadanom vremenu. Prijeđeš li je, moraš pričekati.","also":["rate limit","rate limits","rate limited","limit zahtjeva"]},{"id":"usagelimit","g":"ai","word":"Ograničenje korištenja","text":"Koliko AI rada tvoj plan dopušta u razdoblju, nakon čega staje ili košta više.","also":["usage limit","usage limits","limiti korištenja"]},{"id":"vibe","g":"ai","word":"Vibe coding (kodiranje po osjećaju)","text":"Izrada softvera uglavnom tako da AI-ju opišeš što želiš i pustiš ga da napiše kod.","also":["vibe coding","kodiranje po osjećaju","vibe-coding"]},{"id":"budget","g":"money","word":"Proračun","text":"Iznos novca odvojen za nešto.","also":["proračuni","proračuna","proračunu","budžet","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Procjena troška","text":"Najbolja pretpostavka koliko će nešto koštati prije nego što počneš.","also":["cost estimate","cost estimates","procjena troškova"]},{"id":"roi","g":"money","word":"Povrat ulaganja (ROI)","text":"Što dobiješ natrag u usporedbi s onim što uložiš. Ako je pozitivno, isplatilo se.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Ukupni trošak vlasništva (TCO)","text":"Sve što nešto doista košta tijekom cijelog života, a ne samo cijena kupnje: rad, podrška, nadogradnje i naposljetku gašenje.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx i OpEx","text":"CapEx je novac potrošen unaprijed na stvari koje zadržavaš; OpEx je tekuća potrošnja, poput mjesečnih računa.","also":["CapEx","OpEx","capital expenditure","operating expenditure","kapitalni troškovi","operativni troškovi"]},{"id":"subscription","g":"money","word":"Pretplata","text":"Redovito plaćanje, obično mjesečno ili godišnje, da se nešto može i dalje koristiti.","also":["pretplate","pretplatu","pretplati","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Softver kao usluga (SaaS)","text":"Softver koji koristiš na internetu i plaćaš pretplatom, a izrađivač ga vodi umjesto tebe.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Plaćanje po korištenju","text":"Plaćanje samo onoga što koristiš, poput računalstva u oblaku ili AI tokena.","also":["pay as you go","pay-as-you-go","usage-based pricing","plaćaš koliko koristiš"]},{"id":"overage","g":"money","word":"Prekoračenje plana","text":"Korištenje iznad onoga što plan uključuje, što može koštati dodatno.","also":["overage","overages","overage charges","naknade za prekoračenje"]},{"id":"billingalert","g":"money","word":"Upozorenje o naplati","text":"Poruka kad potrošnja ili korištenje dosegne razinu koju odabereš. Upozorava te, ali ne zaustavlja uvijek daljnje naplate.","also":["billing alert","billing alerts","spending alert","upozorenje o potrošnji"]},{"id":"freetier","g":"money","word":"Besplatna razina","text":"Besplatna razina plaćene usluge, s ograničenjima. Zgodno za početak.","also":["besplatni plan","free tier","free plan"]},{"id":"pricing","g":"money","word":"Cjenovni plan","text":"Različiti paketi koje usluga prodaje, svaki sa svojom cijenom i ograničenjima.","also":["cjenovni planovi","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licenca","text":"Pravila kako smiješ koristiti, kopirati, mijenjati ili dijeliti nešto što je netko drugi napravio, poput softvera, fontova ili slika.","also":["licenca","licence","licencu","license","licenses","licences"],"noTip":1},{"id":"opensource","g":"money","word":"Otvoreni kod (Open source)","text":"Softver čiji kod svatko može čitati, koristiti i često mijenjati besplatno, prema pravilima njegove licence.","also":["open source","open-source","open source software","OSS","softver otvorenog koda"]},{"id":"osslicence","g":"money","word":"Licenca otvorenog koda","text":"Pravila koja dolaze uz softver otvorenog koda. Neka dopuštaju gotovo sve (poput MIT-a); neka traže da podijeliš i svoje promjene (poput GPL-a).","also":["licence otvorenog koda","open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Vlasnički (Proprietary)","text":"U vlasništvu tvrtke, bez slobode kopiranja ili mijenjanja. Suprotno od otvorenog koda.","also":["proprietary","proprietary software","vlasnički softver","zatvoreni kod"]},{"id":"copyright","g":"money","word":"Autorsko pravo","text":"Zakonsko pravo autora da kontrolira primjerke svog djela, uključujući kod i tekst.","also":["copyright","copyrighted","autorska prava"],"noTip":1},{"id":"ip","g":"money","word":"Intelektualno vlasništvo (IP)","text":"Ideje i tvorevine koje zakon smatra vlasništvom, poput koda, dizajna, naziva i logotipa.","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Uvjeti korištenja","text":"Pravila s kojima se slažeš kad koristiš uslugu.","also":["terms of service","terms and conditions","terms of use","opći uvjeti"]},{"id":"contract","g":"money","word":"Ugovor","text":"Pisani dogovor između dviju strana koji zakon podupire.","also":["ugovori","ugovora","ugovoru","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Opis poslova (SOW)","text":"Dokument koji točno navodi koji će se posao obaviti, do kada i za koliko.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Fiksna cijena","text":"Dogovorena cijena za cijeli posao, koliko god trajao.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Vrijeme i materijal","text":"Plaćanje stvarno odrađenih sati i stvarno upotrijebljenih stvari, a ne čvrste cijene.","also":["time and materials","T&M"]},{"id":"invoice","g":"money","word":"Račun","text":"Račun kojim se traži plaćanje za obavljen posao ili isporučenu robu.","also":["računi","računa","faktura","fakture","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vezanost za dobavljača (Vendor lock-in)","text":"Kad je odlazak od dobavljača toliko težak ili skup da od njega praktički više ne možeš otići.","also":["vendor lock-in","lock-in","zaključavanje kod dobavljača"]},{"id":"procurement","g":"money","word":"Nabava (Procurement)","text":"Postupak odabira i kupnje od dobavljača.","also":["nabava","nabave","javna nabava","procurement"]},{"id":"servicecredit","g":"money","word":"Kredit za uslugu","text":"Povrat novca ili popust koji dobiješ kad dobavljač prekrši SLA.","also":["service credit","service credits","krediti za uslugu"]}]}};
